-- Contenu de départ de l'onglet « Apprendre » (généré depuis les fichiers JSON de ce dossier).
-- Les fiches existantes ne sont complétées que pour les champs vides ; rien n'est écrasé.
on conflict (slug) do update set
  formula = coalesce(minerals.formula, excluded.formula),
  chemical_class = coalesce(minerals.chemical_class, excluded.chemical_class),
  crystal_system = coalesce(minerals.crystal_system, excluded.crystal_system),
  hardness = coalesce(minerals.hardness, excluded.hardness),
  hardness_max = coalesce(minerals.hardness_max, excluded.hardness_max),
  density = coalesce(minerals.density, excluded.density),
  density_max = coalesce(minerals.density_max, excluded.density_max),
  colors = case when cardinality(minerals.colors)=0 then excluded.colors else minerals.colors end,
  streak = coalesce(minerals.streak, excluded.streak),
  luster = coalesce(minerals.luster, excluded.luster),
  transparency = coalesce(minerals.transparency, excluded.transparency),
  cleavage = coalesce(minerals.cleavage, excluded.cleavage),
  fracture = coalesce(minerals.fracture, excluded.fracture),
  habit = coalesce(minerals.habit, excluded.habit),
  fluorescence = coalesce(minerals.fluorescence, excluded.fluorescence),
  formation = coalesce(minerals.formation, excluded.formation),
  etymology = coalesce(minerals.etymology, excluded.etymology),
  varieties = coalesce(minerals.varieties, excluded.varieties),
  confusions = coalesce(minerals.confusions, excluded.confusions),
  description = coalesce(minerals.description, excluded.description);

on conflict (slug) do nothing;
