insert into public.minerals (name,slug,formula,chemical_class,crystal_system,hardness,hardness_max,density,density_max,colors,streak,luster,transparency,cleavage,fracture,habit,fluorescence,formation,etymology,varieties,confusions,description,publication_status) values
('Or','or','Au','Éléments natifs','Cubique',2.5,3,15.5,19.3,array['jaune d''or']::text[],'jaune doré','métallique','opaque','aucun','crochue (déchirée)','Pépites, paillettes, grains, dendrites et feuillets ; cristaux octaédriques rares.',null,'Filons de quartz hydrothermaux, souvent avec pyrite et arsénopyrite ; concentré dans les alluvions (placers) grâce à sa forte densité.','Du latin aurum.','Électrum (alliage naturel or–argent, plus pâle).','Pyrite et chalcopyrite (« or des fous ») : plus dures, cassantes, trait noir verdâtre. Mica doré altéré : léger, se délite en paillettes.','Métal noble inaltérable, très malléable et très dense : il se raye au couteau et s''écrase sans se briser. Sa densité élevée (jusqu''à 19,3 à l''état pur, moins s''il contient de l''argent) permet de le récupérer à la batée.','published'),
('Argent','argent','Ag','Éléments natifs','Cubique',2.5,3,10.1,11.1,array['blanc argent','noirci en surface']::text[],'blanc argenté brillant','métallique','opaque','aucun','crochue (déchirée)','Fils torsadés, dendrites, lamelles et masses ; cristaux rares.',null,'Filons hydrothermaux (notamment à cobalt–nickel–arsenic) et zones d''enrichissement de gisements argentifères.','Du latin argentum.',null,'Se ternit en noir (sulfuration) : un spécimen noirci n''est pas forcément un autre minéral. Se distingue des arséniures par sa malléabilité.','Métal malléable et ductile, blanc à l''état frais, qui noircit à l''air. Les « fils d''argent » naturels sont parmi les spécimens les plus recherchés des collectionneurs.','published'),
('Cuivre','cuivre','Cu','Éléments natifs','Cubique',2.5,3,8.9,8.95,array['rouge cuivre','patine brune ou verte']::text[],'rouge cuivre brillant','métallique','opaque','aucun','crochue (déchirée)','Dendrites, plaques, fils et masses ; cristaux cubiques ou dodécaédriques déformés.',null,'Zones d''oxydation et de cémentation des gisements de cuivre ; cavités de basaltes (célèbres gisements du lac Supérieur, Michigan).','Du latin cuprum, de Cyprium aes, « métal de Chypre ».',null,'Sa patine verte peut masquer le métal ; une rayure fraîche révèle la couleur cuivre.','Métal rouge, malléable et excellent conducteur, souvent recouvert d''une patine brune (cuprite) ou verte (malachite).','published'),
('Soufre','soufre','S','Éléments natifs','Orthorhombique',1.5,2.5,2.07,2.07,array['jaune','jaune verdâtre','brun (impur)']::text[],'blanc à jaune pâle','résineux à gras','transparent à translucide','imparfait','conchoïdale à irrégulière','Cristaux bipyramidaux, encroûtements, masses et concrétions.',null,'Fumerolles et solfatares volcaniques ; dômes de sel et évaporites, où il naît de la réduction du gypse par des bactéries.','Du latin sulphur.',null,'Orpiment : plus dense, clivage parfait en lamelles flexibles, toxique.','Élément jaune, léger et fragile. Très mauvais conducteur de la chaleur : un cristal tenu dans la main peut se fendiller sous l''effet de la chaleur. Brûle avec une flamme bleue en dégageant un gaz suffocant.','published'),
('Graphite','graphite','C','Éléments natifs','Hexagonal',1,2,2.09,2.23,array['noir','gris acier']::text[],'noir brillant','métallique à terreux','opaque','parfait basal','irrégulière','Paillettes et lamelles hexagonales, masses foliées ou terreuses.',null,'Métamorphisme de roches riches en matière organique (marbres, gneiss, schistes) ; plus rarement filons.','Du grec graphein, « écrire » : il sert de mine de crayon.',null,'Molybdénite : plus dense, reflet bleuté, trait gris verdâtre sur porcelaine.','Forme de carbone tendre, au toucher gras, qui tache les doigts. Même composition que le diamant mais structure en feuillets : un exemple classique de polymorphisme.','published'),
('Diamant','diamant','C','Éléments natifs','Cubique',10,10,3.51,3.53,array['incolore','jaune','brun','gris','bleu','rose']::text[],'aucun (plus dur que la plaque)','adamantin','transparent à translucide','parfait octaédrique','conchoïdale','Octaèdres, dodécaèdres aux faces arrondies, cubes ; macles aplaties.','Souvent bleue sous ultraviolets.','Cristallise dans le manteau terrestre, au-delà de 150 km de profondeur ; remonté par les kimberlites et les lamproïtes, puis concentré dans les alluvions.','Du grec adamas, « invincible ».',null,'Quartz, zircon incolore, verre et imitations : bien moins durs ; le diamant raye tous les minéraux.','Minéral le plus dur de l''échelle de Mohs (10), mais cassant selon ses plans de clivage. Son éclat adamantin et sa forte dispersion lui donnent ses « feux ».','published'),
('Bismuth','bismuth','Bi','Éléments natifs','Trigonal',2,2.5,9.7,9.8,array['blanc argenté à reflet rosé','irisations en surface']::text[],'gris argenté','métallique','opaque','parfait basal','irrégulière','Lamelles, grains et masses ; cristaux naturels rares.',null,'Filons hydrothermaux de haute température, pegmatites et greisens.','De l''allemand Wismut, d''origine obscure.',null,'Les cristaux « en escalier » vivement irisés du commerce sont des produits de laboratoire, pas des cristaux naturels.','Métal cassant à reflet rosé, qui se couvre d''une fine pellicule d''oxyde irisée. Les spécimens naturels sont discrets, bien loin des cristaux synthétiques colorés.','published'),
('Pyrite','pyrite','FeS₂','Sulfures et sulfosels','Cubique',6,6.5,4.95,5.1,array['jaune laiton pâle']::text[],'noir verdâtre à noir brunâtre','métallique','opaque','indistinct','conchoïdale à irrégulière','Cubes striés, octaèdres, pyritoèdres (dodécaèdres pentagonaux), nodules et disques radiés.',null,'Minéral ubiquiste : filons hydrothermaux, roches sédimentaires (argiles, schistes), roches métamorphiques et magmatiques.','Du grec pyr, « feu » : elle produit des étincelles quand on la frappe.',null,'Or : tendre, malléable, trait jaune. Marcassite : plus pâle, verdâtre, orthorhombique. Chalcopyrite : plus jaune, plus tendre (se raye au couteau).','Le sulfure le plus répandu, surnommé « or des fous ». Certains spécimens s''altèrent à l''humidité (la « maladie de la pyrite ») : les conserver au sec.','published'),
('Marcassite','marcassite','FeS₂','Sulfures et sulfosels','Orthorhombique',6,6.5,4.87,4.92,array['jaune bronze pâle','blanc verdâtre']::text[],'gris à noir brunâtre','métallique','opaque','imparfait','irrégulière','Crêtes de coq, fers de lance (macles), nodules à structure radiée.',null,'Dépôts de basse température : craies, argiles, charbons et filons tardifs.','De l''arabe marqashītā, lui-même d''origine persane.',null,'Pyrite : même formule mais cubique, plus jaune. En bijouterie, la « marcassite » est le plus souvent de la pyrite taillée.','Polymorphe de la pyrite, plus pâle et plus instable : elle se décompose facilement à l''humidité en produisant des sulfates poudreux et de l''acide.','published'),
('Chalcopyrite','chalcopyrite','CuFeS₂','Sulfures et sulfosels','Quadratique',3.5,4,4.1,4.3,array['jaune laiton','irisations bleues et violettes']::text[],'noir verdâtre','métallique','opaque','indistinct','irrégulière','Cristaux pseudo-tétraédriques (sphénoèdres), le plus souvent massive.',null,'Filons hydrothermaux, porphyres cuprifères, amas sulfurés.','Du grec chalkos, « cuivre », et de pyrite.',null,'Pyrite : plus pâle et plus dure. Or : malléable, trait jaune. Une chalcopyrite irisée à l''acide est souvent vendue sous le nom de « minerai paon ».','Principal minerai de cuivre dans le monde, plus jaune et plus tendre que la pyrite.','published'),
('Galène','galene','PbS','Sulfures et sulfosels','Cubique',2.5,2.75,7.4,7.6,array['gris plomb']::text[],'gris plomb','métallique','opaque','parfait cubique (trois directions)','subconchoïdale','Cubes, cubo-octaèdres, masses à gros grains.',null,'Filons hydrothermaux et gisements dans les calcaires (type Mississippi Valley), avec sphalérite, fluorite et baryte.','Du latin galena, nom donné au minerai de plomb.',null,'Sa densité élevée et son clivage en petits cubes la distinguent des autres sulfures gris.','Principal minerai de plomb, souvent argentifère. Lourde, tendre, elle se brise en petits cubes parfaits.','published'),
('Sphalérite','sphalerite','ZnS','Sulfures et sulfosels','Cubique',3.5,4,3.9,4.1,array['brun','noir','jaune miel','rouge','vert','incolore']::text[],'blanc à brun clair','résineux à adamantin','transparent à opaque (selon le fer)','parfait dodécaédrique (six directions)','conchoïdale','Tétraèdres, dodécaèdres, masses clivables, encroûtements.','Parfois orange ou jaune ; certaines sont triboluminescentes.','Filons hydrothermaux, gisements dans les calcaires (type Mississippi Valley), skarns.','Du grec sphaleros, « trompeur » : on la confondait avec la galène sans pouvoir en extraire de plomb.','Blende (nom traditionnel), marmatite (riche en fer, noire), « blende miel » (jaune transparente).','Cassitérite et grenat : bien plus durs. Galène : trait gris et clivage cubique.','Principal minerai de zinc, très variable de couleur selon sa teneur en fer. Son trait clair malgré une couleur sombre est un bon indice.','published'),
('Cinabre','cinabre','HgS','Sulfures et sulfosels','Trigonal',2,2.5,8,8.2,array['rouge vermillon','rouge brunâtre']::text[],'rouge écarlate','adamantin à terne','transparent à opaque','parfait prismatique','subconchoïdale à irrégulière','Cristaux rhomboédriques ou tabulaires, encroûtements, masses granulaires.',null,'Dépôts hydrothermaux de basse température, souvent en régions volcaniques ou près de sources chaudes.','Du grec kinnabari, d''origine probablement orientale.',null,'Réalgar : plus léger, trait orangé. Cuprite : trait rouge brun. Hématite : trait rouge brun, plus dure.','Unique minerai important du mercure, reconnaissable à son rouge vif et à sa densité. Toxique : se laver les mains après manipulation et ne jamais le chauffer.','published'),
('Stibine','stibine','Sb₂S₃','Sulfures et sulfosels','Orthorhombique',2,2,4.6,4.7,array['gris plomb','ternissure noire irisée']::text[],'gris plomb','métallique','opaque','parfait (une direction)','subconchoïdale','Longs prismes striés, aiguilles, gerbes rayonnantes ; cristaux parfois tordus.',null,'Filons hydrothermaux de basse température, souvent avec quartz, pyrite et or.','Du latin stibium, nom antique de l''antimoine. Aussi appelée stibnite.',null,'Bismuthinite : très semblable, mais plus lourde. Les aiguilles fondent à la flamme d''une allumette, ce qui aide à la reconnaître.','Principal minerai d''antimoine, formant de spectaculaires groupes d''aiguilles métalliques. Très tendre et flexible.','published'),
('Réalgar','realgar','As₄S₄','Sulfures et sulfosels','Monoclinique',1.5,2,3.56,3.56,array['rouge','rouge orangé']::text[],'orangé à rouge','résineux à gras','transparent à translucide','bon (une direction)','conchoïdale','Prismes courts striés, grains, encroûtements.',null,'Filons hydrothermaux de basse température, sources chaudes, souvent avec orpiment et stibine.','De l''arabe rahj al-ghār, « poudre de la caverne ».',null,'Cinabre : bien plus dense, trait rouge écarlate. Crocoïte : plus dense, orange vif.','Sulfure d''arsenic toxique qui se dégrade à la lumière en une poudre jaune (pararéalgar) : le conserver dans l''obscurité et se laver les mains après manipulation.','published'),
('Orpiment','orpiment','As₂S₃','Sulfures et sulfosels','Monoclinique',1.5,2,3.49,3.49,array['jaune citron','jaune orangé']::text[],'jaune pâle','résineux, nacré sur le clivage','transparent à translucide','parfait (lamelles flexibles)','irrégulière','Masses foliées, colonnes, cristaux prismatiques rares.',null,'Filons hydrothermaux de basse température, sources chaudes, souvent avec le réalgar.','Du latin auripigmentum, « pigment d''or ».',null,'Soufre : plus léger, sans clivage parfait.','Sulfure d''arsenic jaune d''or, utilisé autrefois comme pigment malgré sa toxicité. Se manipule avec précaution.','published'),
('Molybdénite','molybdenite','MoS₂','Sulfures et sulfosels','Hexagonal',1,1.5,4.62,4.73,array['gris plomb bleuté']::text[],'gris bleuté ; verdâtre sur porcelaine','métallique','opaque','parfait basal (lamelles flexibles)','irrégulière','Tablettes hexagonales, écailles, rosettes.',null,'Granites, pegmatites, greisens, skarns et porphyres à cuivre–molybdène.','Du grec molybdos, « plomb ».',null,'Graphite : plus léger, noir, trait noir sur porcelaine.','Principal minerai de molybdène. Tendre, au toucher gras et se délitant en lamelles, elle ressemble beaucoup au graphite.','published'),
('Pyrrhotite','pyrrhotite','Fe₁₋ₓS','Sulfures et sulfosels','Monoclinique',3.5,4.5,4.58,4.65,array['bronze','brun cuivré (ternie)']::text[],'gris noir','métallique','opaque','aucun (plan de séparation basal)','irrégulière à subconchoïdale','Tablettes et prismes hexagonaux, le plus souvent massive.',null,'Roches magmatiques basiques (gabbros, norites), gisements de nickel–cuivre, skarns et filons.','Du grec pyrrhos, « rougeâtre ».','Il en existe plusieurs polytypes, monocliniques ou hexagonaux.','Pentlandite : non magnétique. Pyrite : plus dure et plus jaune.','Sulfure de fer légèrement déficitaire en fer, souvent magnétique (un petit aimant l’attire), ce qui la distingue des autres sulfures jaunes.','published'),
('Bornite','bornite','Cu₅FeS₄','Sulfures et sulfosels','Orthorhombique',3,3,5.06,5.09,array['rouge cuivre à brun bronze (frais)','irisations violettes et bleues']::text[],'gris noir','métallique','opaque','très imparfait','conchoïdale à irrégulière','Généralement massive ; cristaux pseudo-cubiques rares.',null,'Porphyres cuprifères, filons hydrothermaux, zones d''enrichissement.','Dédiée au minéralogiste autrichien Ignaz von Born.',null,'La chalcopyrite irisée artificiellement est souvent vendue comme « bornite » ou « minerai paon » : une cassure fraîche révèle sa vraie couleur.','Minerai de cuivre dont la surface se couvre rapidement de reflets violets et bleus, d''où son surnom de « minerai paon ».','published'),
('Chalcocite','chalcocite','Cu₂S','Sulfures et sulfosels','Monoclinique',2.5,3,5.5,5.8,array['gris plomb noirâtre']::text[],'gris noir','métallique','opaque','indistinct','conchoïdale','Massive ; cristaux prismatiques pseudo-hexagonaux rares.',null,'Zones de cémentation (enrichissement secondaire) des gisements de cuivre, filons hydrothermaux.','Du grec chalkos, « cuivre ».',null,'Galène : clivage cubique et plus dense. Tétraédrite : plus dure.','Minerai de cuivre très riche (près de 80 % de cuivre), un peu sectile au couteau.','published'),
('Covellite','covellite','CuS','Sulfures et sulfosels','Hexagonal',1.5,2,4.6,4.76,array['bleu indigo','irisations pourpres']::text[],'gris plomb à noir','submétallique à résineux','opaque','parfait basal','irrégulière','Plaquettes hexagonales, lamelles, masses.',null,'Zones de cémentation des gisements de cuivre ; rarement volcanique.','Dédiée au minéralogiste italien Niccolò Covelli, qui l''étudia sur le Vésuve.',null,'Sa couleur bleu indigo métallique est très caractéristique parmi les sulfures.','L''un des rares minéraux naturellement bleu indigo, aux lamelles flexibles irisées de pourpre.','published'),
('Arsénopyrite','arsenopyrite','FeAsS','Sulfures et sulfosels','Monoclinique',5.5,6,5.9,6.2,array['blanc argenté','gris acier']::text[],'gris noir','métallique','opaque','distinct','subconchoïdale à irrégulière','Prismes à section losangique, macles, masses granulaires.',null,'Filons hydrothermaux de haute température, pegmatites, greisens ; souvent associée à l''or.','Arsenic et pyrite. Nom ancien : mispickel.',null,'Marcassite : plus jaune. Cobaltite : teinte rosée, cristaux pseudo-cubiques.','Principal minerai d''arsenic, souvent aurifère. Frappée, elle dégage une odeur d''ail caractéristique : se laver les mains après manipulation.','published'),
('Cobaltite','cobaltite','CoAsS','Sulfures et sulfosels','Orthorhombique',5.5,5.5,6.3,6.3,array['blanc argenté teinté de rose']::text[],'gris noir','métallique','opaque','parfait (pseudo-cubique)','irrégulière','Cristaux pseudo-cubiques et pseudo-pyritoèdres striés, grains.',null,'Filons hydrothermaux de haute température, roches métamorphiques.','Du cobalt, lui-même de l''allemand Kobold, « lutin » des mines.',null,'Pyrite : jaune laiton. Sa teinte rosée et son altération en érythrite rose aident à la reconnaître.','Minerai de cobalt aux cristaux proches de ceux de la pyrite ; s''altère en surface en érythrite rose (« fleur de cobalt »).','published'),
('Millérite','millerite','NiS','Sulfures et sulfosels','Trigonal',3,3.5,5.3,5.5,array['jaune laiton à bronze','ternissure irisée']::text[],'noir verdâtre','métallique','opaque','parfait rhomboédrique','irrégulière','Aiguilles capillaires, gerbes et touffes rayonnantes dans des géodes.',null,'Cavités de calcaires et de nodules de sidérite, roches ultrabasiques serpentinisées, gisements de nickel.','Dédiée au minéralogiste britannique William Hallowes Miller.',null,'Ses fines aiguilles couleur laiton, souvent dans des géodes de calcite, sont très caractéristiques.','Sulfure de nickel en aiguilles dorées très fines, qui tapissent parfois l''intérieur des géodes.','published'),
('Tétraédrite','tetraedrite','Cu₆(Cu₄X₂)Sb₄S₁₃ (X = Fe, Zn…)','Sulfures et sulfosels','Cubique',3.5,4,4.6,5.1,array['gris acier à noir']::text[],'noir à brun, parfois rougeâtre','métallique','opaque','aucun','subconchoïdale à irrégulière','Tétraèdres nets, masses granulaires.',null,'Filons hydrothermaux de moyenne à basse température, avec chalcopyrite, galène et sphalérite.','Du tétraèdre, sa forme cristalline habituelle.','Depuis 2020, l''IMA distingue plusieurs espèces (tétraédrite-(Fe), tétraédrite-(Zn)…) ; tennantite pour le pôle arsenical.','Tennantite : même aspect, riche en arsenic. Chalcocite : plus tendre, sectile.','Sulfosel de cuivre et d''antimoine, souvent argentifère (« cuivre gris »), dont les tétraèdres sont très typiques.','published'),
('Bournonite','bournonite','PbCuSbS₃','Sulfures et sulfosels','Orthorhombique',2.5,3,5.7,5.9,array['gris acier à noir']::text[],'gris noir','métallique','opaque','imparfait','subconchoïdale à irrégulière','Cristaux tabulaires épais, macles répétées en « roue dentée ».',null,'Filons hydrothermaux de moyenne température, avec galène, tétraédrite et sidérite.','Dédiée au minéralogiste français Jacques-Louis de Bournon.',null,'Ses macles en roue dentée (« cogwheel ») sont caractéristiques.','Sulfosel de plomb, cuivre et antimoine, célèbre pour ses macles en forme d''engrenage.','published'),
('Pentlandite','pentlandite','(Fe,Ni)₉S₈','Sulfures et sulfosels','Cubique',3.5,4,4.6,5,array['jaune bronze']::text[],'noir bronze','métallique','opaque','aucun (plan de séparation octaédrique)','conchoïdale','Grains et flammes dans la pyrrhotite, masses.',null,'Roches magmatiques basiques et ultrabasiques ; grands gisements de nickel (Sudbury, Norilsk).','Dédiée au naturaliste irlandais Joseph Barclay Pentland.',null,'Pyrrhotite, avec laquelle elle est intimement associée : la pentlandite n''est pas magnétique.','Principal minerai de nickel, généralement en fines inclusions dans la pyrrhotite.','published'),
('Acanthite','acanthite','Ag₂S','Sulfures et sulfosels','Monoclinique',2,2.5,7.2,7.4,array['gris plomb à noir']::text[],'noir brillant','métallique','opaque','indistinct','subconchoïdale','Cristaux pseudo-cubiques ou octaédriques (pseudomorphoses d''argentite), fils, masses.',null,'Filons hydrothermaux argentifères, zones d''enrichissement.','Du grec akantha, « épine », par allusion à ses cristaux pointus.','L''« argentite » cubique n''est stable qu''au-dessus de 177 °C : les cristaux cubiques trouvés à température ambiante sont de l''acanthite.','Galène : clivage cubique net. L''acanthite se coupe au couteau comme du plomb (sectile).','Principal minerai d''argent, sectile, souvent en cristaux ayant conservé la forme de l''argentite de haute température.','published'),
('Proustite','proustite','Ag₃AsS₃','Sulfures et sulfosels','Trigonal',2,2.5,5.55,5.64,array['rouge écarlate vif']::text[],'rouge vermillon','adamantin','transparent à translucide','distinct rhomboédrique','conchoïdale à irrégulière','Prismes, scalénoèdres, masses.',null,'Filons hydrothermaux argentifères de basse température.','Dédiée au chimiste français Joseph Louis Proust.',null,'Pyrargyrite : plus sombre, trait rouge pourpre. Cinabre : plus dense.','« Argent rouge clair », sulfosel d''argent d''un rouge éclatant, qui noircit à la lumière : à conserver dans l''obscurité.','published'),
('Pyrargyrite','pyrargyrite','Ag₃SbS₃','Sulfures et sulfosels','Trigonal',2.5,2.5,5.82,5.85,array['rouge sombre à noir']::text[],'rouge pourpre','adamantin à submétallique','translucide à opaque','distinct rhomboédrique','conchoïdale à irrégulière','Prismes, scalénoèdres, masses.',null,'Filons hydrothermaux argentifères de basse température.','Du grec pyr, « feu », et argyros, « argent ».',null,'Proustite : plus claire, trait vermillon.','« Argent rouge sombre », minerai d''argent riche en antimoine, sensible à la lumière.','published'),
('Nickeline','nickeline','NiAs','Sulfures et sulfosels','Hexagonal',5,5.5,7.8,7.8,array['rouge cuivre pâle','ternissure grise à noire']::text[],'noir brunâtre','métallique','opaque','aucun','conchoïdale à irrégulière','Généralement massive, réniforme ou en veinules.',null,'Filons hydrothermaux à cobalt–nickel–argent, roches ultrabasiques.','Du nickel, lui-même tiré de Kupfernickel, « faux cuivre du diable », car elle ressemble au cuivre sans en donner.',null,'Cuivre natif : malléable, trait cuivré. Bornite : plus tendre.','Arséniure de nickel à reflet cuivré pâle, qui s''altère en annabergite verte.','published'),
('Boulangérite','boulangerite','Pb₅Sb₄S₁₁','Sulfures et sulfosels','Monoclinique',2.5,3,6,6.3,array['gris plomb bleuté']::text[],'gris brunâtre','métallique','opaque','bon (une direction)','irrégulière','Aiguilles, fibres et masses plumeuses.',null,'Filons hydrothermaux plombo-antimonifères de basse à moyenne température.','Dédiée à l''ingénieur des mines français Charles Boulanger.',null,'Jamesonite et stibine : aspects proches, analyse souvent nécessaire.','Sulfosel de plomb et d''antimoine en fines fibres grises formant des touffes « plumeuses ».','published'),
('Halite','halite','NaCl','Halogénures','Cubique',2,2.5,2.17,2.17,array['incolore','blanc','rose','bleu','orangé']::text[],'blanc','vitreux','transparent à translucide','parfait cubique (trois directions)','conchoïdale','Cubes, cristaux en trémie, masses granulaires.','Parfois rouge ou orangée.','Évaporites marines et lacustres (couches de sel gemme), dômes de sel.','Du grec hals, « sel ».','Sel gemme ; halite bleue (défauts de structure dus à la radioactivité naturelle).','Sylvite : goût plus amer. Calcite : effervescence à l''acide, clivage rhomboédrique.','Le sel de cuisine à l''état naturel : soluble dans l''eau, au goût salé. Craint l''humidité.','published'),
('Sylvite','sylvite','KCl','Halogénures','Cubique',2,2.5,1.99,1.99,array['incolore','blanc','rougeâtre']::text[],'blanc','vitreux','transparent à translucide','parfait cubique (trois directions)','irrégulière','Cubes, masses granulaires, souvent mêlée à la halite.',null,'Évaporites (dernières phases de cristallisation) : gisements de potasse, dont ceux d''Alsace exploités jusqu''en 2002.','Dédiée au médecin François Sylvius de le Boë.',null,'Halite : goût seulement salé, un peu plus dense.','Chlorure de potassium au goût salé et amer, principale source de potasse pour les engrais. Soluble dans l''eau.','published'),
('Fluorite','fluorite','CaF₂','Halogénures','Cubique',4,4,3.18,3.18,array['violet','vert','jaune','bleu','incolore','rose']::text[],'blanc','vitreux','transparent à translucide','parfait octaédrique (quatre directions)','conchoïdale à irrégulière','Cubes, octaèdres, cubo-octaèdres, macles d''interpénétration ; couleurs souvent zonées.','Fréquente, souvent bleue : le phénomène de fluorescence lui doit son nom.','Filons hydrothermaux, souvent avec quartz, baryte, galène et sphalérite ; plus rarement pegmatites et roches sédimentaires.','Du latin fluere, « couler » : elle servait de fondant en métallurgie.','Blue John (rubanée, Derbyshire) ; chlorophane (thermoluminescente).','Calcite : plus tendre, clivage rhomboédrique, effervescence. Quartz : plus dur, sans clivage. Améthyste : plus dure.','Minéral de dureté 4 sur l''échelle de Mohs, aux couleurs très variées et souvent zonées. La France possède de nombreux gisements réputés.','published'),
('Cryolite','cryolite','Na₃AlF₆','Halogénures','Monoclinique',2.5,3,2.95,3,array['incolore','blanc','brunâtre']::text[],'blanc','vitreux à gras','transparent à translucide','aucun (plans de séparation)','irrégulière','Masses à aspect de glace, cristaux pseudo-cubiques rares.',null,'Pegmatites granitiques ; le seul grand gisement, à Ivittuut (Groenland), est épuisé.','Du grec kryos, « glace », et lithos, « pierre ».',null,'Son indice de réfraction proche de celui de l''eau la rend presque invisible une fois immergée.','Fluorure rare autrefois indispensable à la production de l''aluminium, aujourd''hui remplacé par un produit de synthèse.','published'),
('Atacamite','atacamite','Cu₂Cl(OH)₃','Halogénures','Orthorhombique',3,3.5,3.75,3.77,array['vert émeraude','vert noirâtre']::text[],'vert pomme','adamantin à vitreux','transparent à translucide','parfait (une direction)','conchoïdale','Prismes striés, aiguilles, masses fibreuses.',null,'Zones d''oxydation des gisements de cuivre en climat aride et salé.','Du désert d''Atacama (Chili).',null,'Malachite : effervescence à l''acide. Brochantite : vert plus clair, sans chlore (test chimique).','Chlorure de cuivre vert profond, typique des gisements de cuivre des déserts.','published'),
('Quartz','quartz','SiO₂','Oxydes et hydroxydes','Trigonal',7,7,2.65,2.65,array['incolore','blanc','violet','jaune','brun fumé','rose','noir']::text[],'blanc','vitreux','transparent à opaque','aucun (très mauvais)','conchoïdale','Prismes hexagonaux terminés par des rhomboèdres, faces striées horizontalement ; masses, druses, géodes.',null,'Minéral ubiquiste : granites, pegmatites, filons hydrothermaux, fentes alpines, grès, roches métamorphiques.','De l''allemand Quarz, d''origine incertaine.','Cristal de roche, améthyste (violet), citrine (jaune), quartz fumé et morion (brun à noir), quartz rose, calcédoine et agate (microcristallins), jaspe, aventurine, prase.','Calcite : bien plus tendre, clivage rhomboédrique, effervescence. Fluorite : clivage octaédrique, plus tendre. Topaze : clivage basal parfait, plus dense.','L''un des minéraux les plus abondants de l''écorce terrestre. Classé parmi les oxydes (Strunz) ou parmi les silicates de charpente (Dana), il raye le verre et n''a pas de clivage.','published'),
('Améthyste','amethyste','SiO₂','Oxydes et hydroxydes','Trigonal',7,7,2.65,2.65,array['violet pâle à violet profond']::text[],'blanc','vitreux','transparent à translucide','aucun','conchoïdale','Pointements courts en druses et géodes, sceptres ; couleur souvent zonée.',null,'Géodes des basaltes et andésites, filons hydrothermaux, fentes de roches métamorphiques.','Du grec amethystos, « qui n''est pas ivre » : on lui prêtait le pouvoir de préserver de l''ivresse.','Variété violette du quartz ; chauffée, elle peut devenir jaune (citrine chauffée).','Fluorite violette : bien plus tendre, clivage octaédrique.','Variété violette du quartz, colorée par des traces de fer et l''irradiation naturelle. La couleur peut pâlir à une exposition prolongée au soleil.','published'),
('Calcédoine','calcedoine','SiO₂','Oxydes et hydroxydes','Trigonal',6.5,7,2.58,2.64,array['blanc','gris bleuté','brun','rouge','vert']::text[],'blanc','cireux à vitreux','translucide à opaque','aucun','conchoïdale','Mamelons, concrétions, stalactites, remplissages de géodes, nodules.','Parfois verte (traces d''uranium) ou blanche.','Dépôt de silice à basse température : géodes, cavités des laves, silex et nodules des roches sédimentaires.','De Chalcédoine, ancienne cité grecque d''Asie Mineure.','Agate (rubanée), onyx, cornaline (rouge orangé), sardoine, chrysoprase (verte), silex.','Opale : moins dure, plus légère. Quartz cristallisé : faces nettes.','Variété microcristalline du quartz, formée de fibres submicroscopiques, souvent rubanée (agate) et mamelonnée.','published'),
('Opale','opale','SiO₂·nH₂O','Oxydes et hydroxydes','Amorphe',5.5,6.5,1.9,2.3,array['incolore','blanc','jaune','orange','noir','jeux de couleurs']::text[],'blanc','vitreux à résineux','transparent à opaque','aucun','conchoïdale','Masses, rognons, remplissages de fissures, encroûtements (hyalite).','Souvent verte et vive pour la hyalite (traces d''uranium).','Sources chaudes et geysers, altération des roches volcaniques, remplissage de cavités dans les sédiments.','Du latin opalus, peut-être du sanskrit upala, « pierre précieuse ».','Opale noble (jeux de couleurs), opale de feu (orange), hyalite (incolore), opale commune.','Calcédoine : plus dure et plus dense. Verre : pas d''eau, jeux de couleurs absents ou artificiels.','Silice hydratée non cristallisée (minéraloïde). Les jeux de couleurs de l''opale noble viennent de minuscules sphères de silice empilées qui diffractent la lumière. Elle peut se fendiller en se desséchant.','published'),
('Corindon','corindon','Al₂O₃','Oxydes et hydroxydes','Trigonal',9,9,3.95,4.1,array['gris','brun','rouge (rubis)','bleu (saphir)','jaune','violet']::text[],'blanc','adamantin à vitreux','transparent à opaque','aucun (plans de séparation)','conchoïdale à irrégulière','Prismes hexagonaux en tonnelet, bipyramides, tablettes.','Rouge intense pour le rubis (chrome).','Roches métamorphiques pauvres en silice (marbres, gneiss), syénites, basaltes alcalins ; concentré dans les alluvions.','Du tamoul kurundam.','Rubis (rouge), saphir (bleu et toutes les autres couleurs), émeri (roche à corindon et magnétite).','Spinelle rouge : cubique, un peu moins dur. Grenat : cubique, sans forme hexagonale.','Deuxième minéral le plus dur (9 sur l''échelle de Mohs) après le diamant. Ses variétés gemmes sont le rubis et le saphir.','published'),
('Hématite','hematite','Fe₂O₃','Oxydes et hydroxydes','Trigonal',5,6,5.26,5.26,array['gris acier à noir','rouge (terreuse)']::text[],'rouge brun (rouge sang)','métallique à terreux','opaque','aucun (plans de séparation)','irrégulière à subconchoïdale','Tablettes, roses de fer, mamelons (« rognon »), masses terreuses, lamelles brillantes (oligiste).',null,'Sédiments ferrifères, filons hydrothermaux, fentes alpines, fumerolles volcaniques, altération des minéraux de fer.','Du grec haima, « sang », pour la couleur de sa poudre.','Oligiste et spécularite (lamellaires brillantes), rose de fer, hématite rognon, ocre rouge.','Magnétite : trait noir, fortement magnétique. Ilménite : trait noir à brun. Goethite : trait brun jaune.','Principal minerai de fer. Quelle que soit sa couleur, noire et métallique ou rouge et terreuse, son trait rouge brun la trahit.','published'),
('Magnétite','magnetite','Fe₃O₄','Oxydes et hydroxydes','Cubique',5.5,6.5,5.17,5.18,array['noir']::text[],'noir','métallique à submétallique','opaque','aucun (plan de séparation octaédrique)','subconchoïdale à irrégulière','Octaèdres, dodécaèdres, grains, masses ; sables noirs.',null,'Roches magmatiques (basaltes, gabbros), roches métamorphiques, skarns ; concentrée dans les sables de plage et de rivière.','De Magnésie, région de Grèce.','Pierre d''aimant (magnétite naturellement aimantée).','Chromite et ilménite : trait brun, faiblement magnétiques. Hématite : trait rouge.','Minéral le plus magnétique de la nature : il attire fortement un aimant, et certains blocs sont eux-mêmes des aimants naturels.','published'),
('Ilménite','ilmenite','FeTiO₃','Oxydes et hydroxydes','Trigonal',5,6,4.7,4.79,array['noir de fer']::text[],'noir à brun rougeâtre','submétallique','opaque','aucun','conchoïdale à irrégulière','Tablettes épaisses, grains, masses ; sables.',null,'Roches magmatiques basiques (gabbros, anorthosites), pegmatites ; concentrée dans les sables noirs.','Des monts Ilmen (Oural, Russie).',null,'Magnétite : fortement magnétique. Hématite : trait rouge franc.','Principal minerai de titane, faiblement magnétique, fréquent dans les sables noirs.','published'),
('Rutile','rutile','TiO₂','Oxydes et hydroxydes','Quadratique',6,6.5,4.2,4.3,array['rouge','brun rouge','jaune doré','noir']::text[],'brun pâle','adamantin à submétallique','transparent à opaque','bon (une direction)','conchoïdale à irrégulière','Prismes striés, aiguilles, macles en genou, réseaux d''aiguilles entrecroisées (sagénite).',null,'Roches métamorphiques, pegmatites, fentes alpines, filons de quartz ; résiste à l''altération et se retrouve dans les sables.','Du latin rutilus, « rouge ».','Sagénite (réseaux d''aiguilles) ; aiguilles dorées incluses dans le « quartz rutilé ».','Cassitérite : bien plus dense. Tourmaline : section triangulaire, sans éclat adamantin.','Oxyde de titane aux aiguilles dorées ou rouges, célèbre en inclusions dans le quartz. Polymorphe de l''anatase et de la brookite.','published'),
('Anatase','anatase','TiO₂','Oxydes et hydroxydes','Quadratique',5.5,6,3.79,3.97,array['brun','bleu noir','jaune','gris']::text[],'blanc à jaune pâle','adamantin à submétallique','transparent à opaque','parfait (deux directions)','subconchoïdale','Bipyramides aiguës très allongées, tablettes.',null,'Fentes alpines, filons, roches métamorphiques ; produit d''altération d''autres minéraux titanés.','Du grec anatasis, « élévation », pour ses bipyramides allongées.',null,'Ses bipyramides aiguës à éclat adamantin, souvent petites, sont caractéristiques.','Polymorphe du rutile en petites bipyramides pointues très brillantes, classique des fentes alpines.','published'),
('Cassitérite','cassiterite','SnO₂','Oxydes et hydroxydes','Quadratique',6,7,6.98,7.01,array['brun','noir','jaune','rougeâtre']::text[],'blanc à brunâtre','adamantin à submétallique','transparent à opaque','imparfait','subconchoïdale à irrégulière','Prismes courts, bipyramides, macles en genou (« bec d''étain »), grains, masses fibreuses (étain de bois).',null,'Greisens, pegmatites, filons de quartz liés aux granites ; concentrée dans les alluvions.','Du grec kassiteros, « étain ».','Étain de bois (concrétionné fibreux).','Sphalérite : plus tendre, clivage parfait. Wolframite : clivage parfait, trait brun sombre. Sa densité élevée la trahit.','Principal minerai d''étain, lourd et dur, reconnaissable à ses macles en « bec d''étain ».','published'),
('Cuprite','cuprite','Cu₂O','Oxydes et hydroxydes','Cubique',3.5,4,6.1,6.15,array['rouge carmin','rouge presque noir']::text[],'rouge brun','adamantin à submétallique','transparent à translucide','médiocre octaédrique','conchoïdale à irrégulière','Octaèdres, cubes, dodécaèdres ; aiguilles capillaires (chalcotrichite) ; masses.',null,'Zones d''oxydation des gisements de cuivre, souvent avec cuivre natif, malachite et azurite.','Du latin cuprum, « cuivre ».','Chalcotrichite (aiguilles capillaires rouges).','Cinabre : trait rouge écarlate, plus dense. Hématite : plus dure, non transparente.','Oxyde de cuivre rouge sombre, montrant des reflets rouge rubis par transparence dans les petits cristaux.','published'),
('Spinelle','spinelle','MgAl₂O₄','Oxydes et hydroxydes','Cubique',7.5,8,3.58,3.61,array['rouge','rose','bleu','violet','noir','vert']::text[],'blanc','vitreux','transparent à opaque','indistinct','conchoïdale à irrégulière','Octaèdres, macles aplaties (macle du spinelle), grains roulés.','Rouge pour les spinelles au chrome.','Marbres et roches métamorphiques, péridotites ; concentré dans les alluvions à gemmes.','Probablement du latin spina, « épine », pour ses cristaux pointus.','Le célèbre « rubis du Prince Noir » de la couronne britannique est un spinelle.','Rubis (corindon) : trigonal, plus dur. Grenat : autres formes (dodécaèdres), densité différente.','Gemme longtemps confondue avec le rubis, en octaèdres aux arêtes vives. A donné son nom à la « macle du spinelle ».','published'),
('Chromite','chromite','FeCr₂O₄','Oxydes et hydroxydes','Cubique',5.5,5.5,4.5,4.8,array['noir','noir brunâtre']::text[],'brun','métallique à submétallique','opaque','aucun','irrégulière','Grains, masses granulaires ; octaèdres rares.',null,'Péridotites, dunites et serpentinites, souvent en couches ou en amas.','Du chrome, qu''elle contient.',null,'Magnétite : trait noir, fortement magnétique.','Seul minerai important du chrome, faiblement magnétique, dont le trait brun la distingue de la magnétite.','published'),
('Chrysobéryl','chrysoberyl','BeAl₂O₄','Oxydes et hydroxydes','Orthorhombique',8.5,8.5,3.7,3.8,array['jaune','vert','brun','vert–rouge (alexandrite)']::text[],'blanc','vitreux','transparent à translucide','distinct','conchoïdale','Tablettes, macles cycliques pseudo-hexagonales (trilles).',null,'Pegmatites granitiques, micaschistes ; concentré dans les alluvions.','Du grec chrysos, « or », et de béryl.','Alexandrite (verte à la lumière du jour, rouge à la lumière artificielle), cymophane (œil-de-chat).','Béryl : hexagonal, moins dur. Ses macles en étoile à six branches sont caractéristiques.','Gemme très dure (8,5) dont les variétés alexandrite et œil-de-chat sont parmi les plus prisées.','published'),
('Pyrolusite','pyrolusite','MnO₂','Oxydes et hydroxydes','Quadratique',6,6.5,4.4,5.06,array['noir','gris acier']::text[],'noir','métallique à terreux','opaque','parfait (une direction)','irrégulière','Masses fibreuses rayonnantes, encroûtements, masses terreuses tendres qui tachent les doigts.',null,'Zones d''oxydation des gisements de manganèse, dépôts de marais et de lacs, altération de roches.','Du grec pyr, « feu », et louein, « laver » : elle servait à décolorer le verre.',null,'Les « dendrites » noires des roches, souvent attribuées à la pyrolusite, sont en général d''autres oxydes de manganèse. Manganite : trait brun.','Principal minerai de manganèse. Dure en cristaux (6 à 6,5), elle est souvent terreuse et tendre, et tache alors les doigts.','published'),
('Goethite','goethite','FeO(OH)','Oxydes et hydroxydes','Orthorhombique',5,5.5,3.3,4.3,array['brun noir','brun jaune','brun rouge']::text[],'brun jaune (ocre)','submétallique, soyeux ou terreux','opaque','parfait (une direction)','irrégulière','Mamelons et stalactites à structure fibro-radiée, aiguilles, pseudomorphoses de pyrite, masses terreuses.',null,'Altération de tous les minéraux de fer ; « chapeaux de fer » au sommet des gisements sulfurés, sols et marais.','Dédiée à l''écrivain et naturaliste allemand Johann Wolfgang von Goethe.','La « limonite » n''est pas une espèce mais un mélange d''hydroxydes de fer dominé par la goethite.','Hématite : trait rouge brun. Pyrolusite : trait noir.','Hydroxyde de fer très commun, responsable de nombreuses couleurs rouille et ocre. Son trait brun jaune la distingue de l''hématite.','published'),
('Brucite','brucite','Mg(OH)₂','Oxydes et hydroxydes','Trigonal',2.5,3,2.39,2.39,array['blanc','gris','vert pâle','bleuté']::text[],'blanc','vitreux, nacré sur le clivage','transparent à translucide','parfait basal','irrégulière','Tablettes, masses foliées, fibres (némalite).',null,'Serpentinites, marbres métamorphiques (dolomies métamorphisées).','Dédiée au minéralogiste américain Archibald Bruce.','Némalite (fibreuse).','Talc et gypse : plus tendres. Micas : lamelles élastiques (celles de la brucite ne reprennent pas leur forme).','Hydroxyde de magnésium tendre à éclat nacré, dont les lamelles sont flexibles mais non élastiques.','published'),
('Uraninite','uraninite','UO₂','Oxydes et hydroxydes','Cubique',5,6,6.5,10.95,array['noir','noir brunâtre']::text[],'noir brunâtre','submétallique, résineux (« poix »)','opaque','aucun','conchoïdale à irrégulière','Cubes et octaèdres (pegmatites), masses botryoïdales (pechblende).',null,'Pegmatites granitiques, filons hydrothermaux liés aux granites, gisements sédimentaires.','De l''uranium, qu''elle contient.','Pechblende (variété massive, moins dense).','Sa densité très élevée et sa radioactivité la distinguent des autres minéraux noirs.','Principal minerai d''uranium. Fortement radioactive : à stocker à l''écart des lieux de vie, à manipuler peu et avec des gants, et à ne jamais réduire en poudre.','published'),
('Manganite','manganite','MnO(OH)','Oxydes et hydroxydes','Monoclinique',4,4,4.29,4.34,array['gris acier','noir']::text[],'brun rougeâtre à noir','submétallique','opaque','parfait (une direction)','irrégulière','Prismes striés groupés en faisceaux, masses fibreuses.',null,'Filons hydrothermaux de basse température, dépôts sédimentaires de manganèse.','Du manganèse, qu''elle contient.',null,'Pyrolusite : trait noir, souvent pseudomorphe de la manganite.','Hydroxyde de manganèse en prismes noirs striés, qui s''altère souvent en pyrolusite en conservant sa forme.','published'),
('Wolframite','wolframite','(Fe,Mn)WO₄','Oxydes et hydroxydes','Monoclinique',4,4.5,7,7.5,array['brun noir','noir']::text[],'brun rouge à noir','submétallique à résineux','opaque','parfait (une direction)','irrégulière','Prismes tabulaires épais, lames, masses.',null,'Greisens et filons de quartz liés aux granites, avec cassitérite ; pegmatites.','De l''allemand Wolf rahm, « écume de loup » : le minerai « dévorait » l''étain lors de la fonte.','Nom de série entre la ferbérite (fer) et la hübnérite (manganèse).','Cassitérite : sans clivage parfait, trait clair. Sa forte densité est remarquable.','Principal minerai de tungstène avec la scheelite, très lourd, au clivage parfait.','published'),
('Gibbsite','gibbsite','Al(OH)₃','Oxydes et hydroxydes','Monoclinique',2.5,3.5,2.38,2.42,array['blanc','gris','vert pâle','rosé']::text[],'blanc','vitreux, nacré sur le clivage','transparent à translucide','parfait basal','irrégulière','Tablettes pseudo-hexagonales, mamelons, encroûtements, masses.',null,'Constituant principal des bauxites, produits d''altération tropicale des roches ; plus rarement filons.','Dédiée au collectionneur américain George Gibbs.',null,'Talc et brucite : aspect proche, analyse souvent nécessaire.','Hydroxyde d''aluminium, principal constituant des bauxites, dont le nom vient des Baux-de-Provence.','published'),
('Calcite','calcite','CaCO₃','Carbonates','Trigonal',3,3,2.71,2.71,array['incolore','blanc','jaune miel','orange','rose','vert','bleu','brun']::text[],'blanc','vitreux','transparent à opaque','parfait rhomboédrique (trois directions)','conchoïdale','Scalénoèdres (« dents de cochon »), rhomboèdres, prismes, stalactites ; plusieurs centaines de formes connues.','Fréquente et variée (rouge, rose, bleue, jaune).','Roches sédimentaires (calcaires, craie), marbres, filons hydrothermaux, grottes (stalactites), géodes.','Du latin calx, « chaux ».','Spath d''Islande (limpide, double réfraction spectaculaire), calcite cobaltifère (rose), calcite manganésifère.','Aragonite : orthorhombique, sans clivage rhomboédrique. Dolomite : effervescence faible à froid. Quartz : raye le verre. Baryte : bien plus lourde.','Carbonate le plus commun, référence de dureté 3. Elle fait effervescence à froid avec un acide dilué et se clive en rhomboèdres parfaits.','published'),
('Aragonite','aragonite','CaCO₃','Carbonates','Orthorhombique',3.5,4,2.93,2.95,array['incolore','blanc','jaune','brun','bleu','violet']::text[],'blanc','vitreux','transparent à translucide','distinct (une direction)','subconchoïdale','Aiguilles, prismes, macles pseudo-hexagonales, formes coralloïdes (« fleurs de fer »).','Parfois jaune, verte ou blanche.','Grottes, sources thermales, zones d''oxydation, cavités de basaltes ; coquilles et perles.','De l''Aragon (Espagne), où ses macles pseudo-hexagonales furent décrites.','Fleurs de fer (coralloïdes blanches).','Calcite : clivage rhomboédrique parfait, moins dense. Strontianite et cérusite : plus denses.','Polymorphe de la calcite, instable à long terme : avec le temps, elle se transforme en calcite. Fait aussi effervescence à l''acide.','published'),
('Dolomite','dolomite','CaMg(CO₃)₂','Carbonates','Trigonal',3.5,4,2.84,2.86,array['blanc','rose','gris','incolore','brunâtre']::text[],'blanc','vitreux à nacré','transparent à translucide','parfait rhomboédrique','subconchoïdale','Rhomboèdres aux faces courbes (« en selle »), masses granulaires.',null,'Roches sédimentaires (dolomies), filons hydrothermaux, marbres.','Dédiée au géologue français Déodat de Dolomieu, qui a aussi donné son nom aux Dolomites.',null,'Calcite : effervescence vive à froid. Sidérite : plus dense, brune.','Carbonate de calcium et de magnésium qui ne réagit que faiblement à l''acide froid, sauf réduit en poudre. Ses rhomboèdres courbes sont caractéristiques.','published'),
('Sidérite','siderite','FeCO₃','Carbonates','Trigonal',3.75,4.25,3.96,3.96,array['brun jaune','brun sombre','gris']::text[],'blanc','vitreux à nacré','translucide','parfait rhomboédrique','irrégulière','Rhomboèdres souvent courbes, masses clivables, nodules (« fer des houillères »).',null,'Filons hydrothermaux, roches sédimentaires (argiles, bassins houillers), pegmatites.','Du grec sideros, « fer ».',null,'Dolomite et ankérite : plus claires, moins denses. Rhodochrosite : rose.','Carbonate de fer qui brunit en s''altérant. Ne fait effervescence qu''à chaud ou en poudre. Ancien minerai de fer.','published'),
('Rhodochrosite','rhodochrosite','MnCO₃','Carbonates','Trigonal',3.5,4,3.69,3.69,array['rose','rouge framboise','orangé']::text[],'blanc','vitreux à nacré','transparent à translucide','parfait rhomboédrique','irrégulière','Rhomboèdres, stalactites et concrétions rubanées.',null,'Filons hydrothermaux de moyenne à basse température, zones d''oxydation du manganèse.','Du grec rhodon, « rose », et chroma, « couleur ».',null,'Rhodonite : plus dure (5,5–6,5), sans effervescence, veines noires. Calcite rose : plus légère.','Carbonate de manganèse rose framboise, dont les stalactites rubanées sont polies en bijouterie.','published'),
('Magnésite','magnesite','MgCO₃','Carbonates','Trigonal',3.5,4.5,2.98,3.02,array['blanc','gris','jaunâtre','brunâtre']::text[],'blanc','vitreux ; terne pour la variété porcelanée','transparent à opaque','parfait rhomboédrique','conchoïdale','Masses porcelanées, granulaires ; rhomboèdres rares.',null,'Altération des serpentinites et péridotites, roches métamorphiques, évaporites.','De Magnésie (Grèce).',null,'Howlite et magnésite teintes sont vendues comme imitations de turquoise. Calcite : effervescence vive à froid.','Carbonate de magnésium blanc, souvent en masses à cassure de porcelaine. N''effervesce qu''à chaud.','published'),
('Smithsonite','smithsonite','ZnCO₃','Carbonates','Trigonal',4,4.5,4.4,4.5,array['blanc','bleu','vert','rose','jaune','gris']::text[],'blanc','vitreux à nacré','translucide','parfait rhomboédrique','irrégulière','Mamelons botryoïdaux, encroûtements, stalactites ; cristaux rhomboédriques rares.','Parfois bleu-blanc ou rose.','Zones d''oxydation des gisements de zinc dans les calcaires.','Dédiée au chimiste britannique James Smithson, fondateur de la Smithsonian Institution.',null,'Hémimorphite : plus dure, pas d''effervescence. Calcédoine : bien plus dure et plus légère.','Carbonate de zinc aux mamelons soyeux de couleurs douces, remarquablement dense pour un minéral clair.','published'),
('Cérusite','cerusite','PbCO₃','Carbonates','Orthorhombique',3,3.5,6.53,6.58,array['incolore','blanc','gris','noirâtre']::text[],'blanc','adamantin','transparent à translucide','distinct (deux directions)','conchoïdale','Macles réticulées en treillis, macles en étoile à six branches, tablettes.','Parfois jaune ou bleutée.','Zones d''oxydation des gisements de plomb.','Du latin cerussa, « blanc de plomb ».',null,'Anglésite : pas d''effervescence. Sa densité très élevée pour un minéral incolore est un bon indice.','Carbonate de plomb incolore à éclat adamantin très vif, célèbre pour ses macles en treillis. Fait effervescence à l''acide.','published'),
('Malachite','malachite','Cu₂CO₃(OH)₂','Carbonates','Monoclinique',3.5,4,3.6,4.05,array['vert vif à vert sombre (zoné)']::text[],'vert pâle','soyeux, adamantin ou terne','translucide à opaque','parfait (une direction)','subconchoïdale à irrégulière','Mamelons à rubanement concentrique, fibres rayonnantes, stalactites, encroûtements ; cristaux aciculaires rares.',null,'Zones d''oxydation des gisements de cuivre, souvent avec azurite, cuprite et chrysocolle.','Du grec malakhê, « mauve », par analogie de couleur avec les feuilles de cette plante.',null,'Chrysocolle : bleu-vert, pas d''effervescence. Brochantite et atacamite : pas d''effervescence.','Carbonate de cuivre vert aux bandes concentriques caractéristiques. Fait effervescence à l''acide. Souvent issue de la transformation de l''azurite.','published'),
('Azurite','azurite','Cu₃(CO₃)₂(OH)₂','Carbonates','Monoclinique',3.5,4,3.77,3.78,array['bleu azur','bleu profond']::text[],'bleu clair','vitreux','transparent à translucide','parfait (une direction)','conchoïdale','Cristaux tabulaires ou prismatiques, rosettes, nodules, encroûtements.',null,'Zones d''oxydation des gisements de cuivre. Chessy-les-Mines (Rhône), gisement historique, a donné le synonyme « chessylite ».','Du persan lazhward, « bleu ».',null,'Linarite : pas d''effervescence, plus dense. Lazulite : bien plus dure.','Carbonate de cuivre d''un bleu intense. Elle se transforme lentement en malachite, parfois en gardant sa forme (pseudomorphose).','published'),
('Witherite','witherite','BaCO₃','Carbonates','Orthorhombique',3,3.5,4.29,4.29,array['incolore','blanc','gris','jaune pâle']::text[],'blanc','vitreux','transparent à translucide','distinct (une direction)','irrégulière','Macles pseudo-hexagonales bipyramidales, masses globulaires.','Parfois bleu-blanc.','Filons hydrothermaux de basse température, avec baryte et galène.','Dédiée au médecin et botaniste britannique William Withering.',null,'Baryte : pas d''effervescence. Calcite : bien plus légère.','Carbonate de baryum lourd, toxique en cas d''ingestion, qui fait effervescence à l''acide.','published'),
('Strontianite','strontianite','SrCO₃','Carbonates','Orthorhombique',3.5,3.5,3.74,3.78,array['incolore','blanc','gris','jaune pâle','vert pâle']::text[],'blanc','vitreux','transparent à translucide','presque parfait (une direction)','subconchoïdale','Aiguilles, gerbes, prismes, masses fibreuses.','Fréquente (bleue, blanche ou jaune).','Filons hydrothermaux de basse température, géodes et nodules de calcaires.','De Strontian (Écosse), où le strontium fut découvert.',null,'Aragonite : plus légère. Célestine : pas d''effervescence.','Carbonate de strontium en fines aiguilles ; le strontium colore la flamme en rouge vif.','published'),
('Ankérite','ankerite','Ca(Fe,Mg,Mn)(CO₃)₂','Carbonates','Trigonal',3.5,4,2.93,3.1,array['blanc','jaune brun','brun']::text[],'blanc','vitreux à nacré','translucide','parfait rhomboédrique','subconchoïdale','Rhomboèdres courbes, masses clivables.',null,'Filons hydrothermaux (notamment aurifères), roches sédimentaires et métamorphiques.','Dédiée au minéralogiste autrichien Matthias Anker.',null,'Dolomite : plus claire, ne brunit pas. Sidérite : plus dense.','Proche de la dolomite, mais riche en fer : elle brunit en s''altérant.','published'),
('Aurichalcite','aurichalcite','(Zn,Cu)₅(CO₃)₂(OH)₆','Carbonates','Monoclinique',1,2,3.64,3.96,array['bleu vert pâle','bleu ciel']::text[],'bleu pâle','soyeux à nacré','transparent à translucide','parfait','irrégulière','Houppes d''aiguilles et de lamelles délicates, encroûtements.',null,'Zones d''oxydation des gisements de zinc et de cuivre.','Du latin aurichalcum, nom d''un alliage de type laiton.',null,'Rosasite : sphérules plus dures. Hémimorphite bleue : bien plus dure.','Carbonate de zinc et de cuivre en houppes soyeuses bleu ciel, très fragiles.','published'),
('Hydrozincite','hydrozincite','Zn₅(CO₃)₂(OH)₆','Carbonates','Monoclinique',2,2.5,3.5,4,array['blanc','gris','jaunâtre']::text[],'blanc','soyeux, terne à nacré','translucide à opaque','parfait (une direction)','irrégulière','Encroûtements, masses terreuses ou concrétionnées.','Bleu-blanc vive sous ultraviolets courts, caractéristique.','Zones d''oxydation des gisements de zinc.','De hydro (eau, hydroxyde) et zinc.',null,'Sa fluorescence bleu-blanc intense sous UV courts l''identifie facilement parmi les encroûtements blancs.','Carbonate de zinc blanc, discret en lumière du jour mais spectaculaire sous lampe UV.','published'),
('Rosasite','rosasite','(Cu,Zn)₂CO₃(OH)₂','Carbonates','Monoclinique',4,4,4,4.2,array['bleu vert','vert']::text[],'bleu clair','soyeux à vitreux','translucide','parfait (deux directions)','irrégulière','Sphérules et mamelons à structure fibro-radiée.',null,'Zones d''oxydation des gisements de cuivre et de zinc.','De la mine de Rosas (Sardaigne).',null,'Malachite : vert plus franc, bandes concentriques. Aurichalcite : houppes plus tendres.','Carbonate de cuivre et de zinc en petites sphères bleu-vert veloutées.','published'),
('Baryte','baryte','BaSO₄','Sulfates, chromates, molybdates et tungstates','Orthorhombique',3,3.5,4.3,4.6,array['incolore','blanc','jaune','bleu','brun','rose']::text[],'blanc','vitreux à nacré','transparent à opaque','parfait (une direction), bon (deux autres)','irrégulière','Tablettes, crêtes de coq, rosettes, « roses des sables », masses lamellaires.','Parfois jaune, blanche ou bleutée.','Filons hydrothermaux (avec fluorite, galène, sphalérite), concrétions sédimentaires, sources chaudes.','Du grec barys, « lourd ».','Rose des sables de baryte ; « bologne » (baryte radiée phosphorescente de Bologne).','Calcite : bien plus légère, effervescence. Célestine : un peu moins dense, souvent bleu ciel.','Sulfate de baryum remarquablement lourd pour un minéral clair, d''où son nom. Très commun dans les filons avec la fluorite.','published'),
('Célestine','celestine','SrSO₄','Sulfates, chromates, molybdates et tungstates','Orthorhombique',3,3.5,3.96,3.98,array['incolore','bleu ciel','blanc','orangé']::text[],'blanc','vitreux, nacré sur le clivage','transparent à translucide','parfait (une direction), bon (deux autres)','irrégulière','Tablettes, prismes, géodes tapissées de cristaux, masses fibreuses.','Parfois bleu-blanc.','Roches sédimentaires (calcaires, marnes), évaporites, géodes ; plus rarement filons hydrothermaux.','Du latin caelestis, « céleste », pour sa teinte bleu ciel.',null,'Baryte : plus dense. Le strontium colore la flamme en rouge vif.','Sulfate de strontium souvent bleu ciel, célèbre pour ses grandes géodes de Madagascar.','published'),
('Gypse','gypse','CaSO₄·2H₂O','Sulfates, chromates, molybdates et tungstates','Monoclinique',2,2,2.31,2.33,array['incolore','blanc','gris','jaunâtre','brun']::text[],'blanc','vitreux, nacré ou soyeux','transparent à opaque','parfait (une direction, lamelles flexibles)','conchoïdale ou fibreuse','Prismes, macles en fer de lance ou en queue d''aronde, roses des sables, masses fibreuses ou saccharoïdes.','Parfois blanche ou jaunâtre.','Évaporites, argiles et marnes, zones d''oxydation de sulfures, dépôts de fumerolles. La « pierre à plâtre » du Bassin parisien (Montmartre) a donné le « plâtre de Paris ».','Du grec gypsos, « plâtre ».','Sélénite (cristaux transparents), albâtre (massif à grain fin), gypse fibreux (satiné), rose des sables.','Calcite : plus dure, effervescence. Anhydrite : plus dure, trois clivages à angle droit.','Référence de dureté 2 : il se raye à l''ongle. Chauffé, il perd son eau et donne le plâtre. Soluble dans l''eau : ne pas le laver longuement.','published'),
('Anhydrite','anhydrite','CaSO₄','Sulfates, chromates, molybdates et tungstates','Orthorhombique',3.5,3.5,2.97,2.98,array['incolore','blanc','bleu lavande','gris','rosé']::text[],'blanc','vitreux à nacré','transparent à translucide','parfait en trois directions à angle droit','irrégulière','Masses granulaires ou fibreuses ; cristaux prismatiques rares.',null,'Évaporites et dômes de sel ; plus rarement filons hydrothermaux.','Du grec anhydros, « sans eau ».','Angélite (anhydrite bleu lavande du Pérou, nom commercial).','Gypse : plus tendre (se raye à l''ongle). Calcite : effervescence, clivage rhomboédrique.','Sulfate de calcium sans eau, qui se transforme en gypse en s''hydratant, avec gonflement.','published'),
('Anglésite','anglesite','PbSO₄','Sulfates, chromates, molybdates et tungstates','Orthorhombique',2.5,3,6.3,6.4,array['incolore','blanc','gris','jaune','vert pâle']::text[],'blanc','adamantin','transparent à translucide','bon (une direction)','conchoïdale','Prismes, tablettes, masses granulaires entourant la galène.','Parfois jaune.','Zones d''oxydation des gisements de plomb, souvent directement sur la galène.','De l''île d''Anglesey (Pays de Galles).',null,'Cérusite : fait effervescence à l''acide. Baryte : moins dense, moins brillante.','Sulfate de plomb à éclat adamantin, issu de l''altération de la galène.','published'),
('Chalcanthite','chalcanthite','CuSO₄·5H₂O','Sulfates, chromates, molybdates et tungstates','Triclinique',2.5,2.5,2.28,2.28,array['bleu vif','bleu ciel']::text[],'blanc','vitreux','transparent à translucide','imparfait','conchoïdale','Stalactites, encroûtements, fibres ; cristaux naturels rares.',null,'Zones d''oxydation des gisements de cuivre en climat aride, galeries de mines.','Du grec chalkos, « cuivre », et anthos, « fleur ».',null,'Les grands cristaux bleus du commerce sont presque toujours cultivés en laboratoire (sulfate de cuivre).','Sulfate de cuivre bleu, soluble dans l''eau et toxique, qui se déshydrate en poudre blanche à l''air sec.','published'),
('Brochantite','brochantite','Cu₄SO₄(OH)₆','Sulfates, chromates, molybdates et tungstates','Monoclinique',3.5,4,3.97,3.97,array['vert émeraude','vert noirâtre']::text[],'vert clair','vitreux','transparent à translucide','parfait (une direction)','conchoïdale à irrégulière','Aiguilles, prismes, encroûtements.',null,'Zones d''oxydation des gisements de cuivre, surtout en climat aride.','Dédiée au géologue français André Brochant de Villiers.',null,'Malachite : effervescence à l''acide. Atacamite : contient du chlore, vert plus sombre.','Sulfate de cuivre vert émeraude en aiguilles, qui ne fait pas effervescence à l''acide.','published'),
('Linarite','linarite','PbCu(SO₄)(OH)₂','Sulfates, chromates, molybdates et tungstates','Monoclinique',2.5,2.5,5.3,5.35,array['bleu azur intense']::text[],'bleu pâle','subadamantin','transparent à translucide','parfait (une direction)','conchoïdale','Prismes allongés, tablettes, encroûtements.',null,'Zones d''oxydation des gisements de plomb et de cuivre.','De Linares (Espagne).',null,'Azurite : fait effervescence à l''acide, moins dense.','Sulfate de plomb et de cuivre d''un bleu intense, souvent confondu avec l''azurite.','published'),
('Alunite','alunite','KAl₃(SO₄)₂(OH)₆','Sulfates, chromates, molybdates et tungstates','Trigonal',3.5,4,2.6,2.9,array['blanc','gris','jaunâtre','rougeâtre']::text[],'blanc','vitreux à nacré','transparent à translucide','bon basal','conchoïdale à irrégulière','Masses granulaires ou terreuses ; petits rhomboèdres pseudo-cubiques.',null,'Altération hydrothermale acide des roches volcaniques, fumerolles.','De l''alun, qu''on en extrayait.',null,'Aspect de roche claire compacte : analyse souvent nécessaire.','Sulfate d''aluminium et de potassium, source historique de l''alun.','published'),
('Jarosite','jarosite','KFe₃(SO₄)₂(OH)₆','Sulfates, chromates, molybdates et tungstates','Trigonal',2.5,3.5,2.9,3.26,array['jaune ocre','brun jaune','brun']::text[],'jaune pâle','subadamantin à vitreux','translucide','bon basal','irrégulière','Petits rhomboèdres, croûtes, masses terreuses.',null,'Altération des sulfures de fer en milieu acide (chapeaux de fer, haldes de mines).','Du Barranco Jaroso (Espagne).',null,'Goethite : trait brun jaune plus sombre. Ocres : mélanges terreux.','Sulfate de fer jaune ocre, indicateur de milieux acides ; il a été détecté sur Mars.','published'),
('Crocoïte','crocoite','PbCrO₄','Sulfates, chromates, molybdates et tungstates','Monoclinique',2.5,3,5.97,6.02,array['orange vif','rouge orangé']::text[],'jaune orangé','adamantin','translucide','distinct','conchoïdale à irrégulière','Prismes allongés et creux, entrelacés en amas.',null,'Zones d''oxydation de gisements de plomb au contact de roches riches en chrome (Tasmanie, Oural).','Du grec krokos, « safran ».',null,'Réalgar : plus léger, trait orangé à rouge. Wulfénite : tablettes carrées.','Chromate de plomb orange éclatant ; c''est en l''étudiant que Vauquelin découvrit le chrome en 1797. Fragile et toxique.','published'),
('Wulfénite','wulfenite','PbMoO₄','Sulfates, chromates, molybdates et tungstates','Quadratique',2.5,3,6.5,7.5,array['orange','jaune miel','rouge','brun','incolore']::text[],'blanc','adamantin à résineux','transparent à translucide','distinct','subconchoïdale','Tablettes carrées très fines, bipyramides, encroûtements.',null,'Zones d''oxydation des gisements de plomb et de molybdène.','Dédiée au minéralogiste autrichien Franz Xaver von Wulfen.',null,'Crocoïte : prismes allongés, trait orangé. Vanadinite : prismes hexagonaux.','Molybdate de plomb en fines tablettes carrées orange ou jaune miel, très recherché des collectionneurs.','published'),
('Scheelite','scheelite','CaWO₄','Sulfates, chromates, molybdates et tungstates','Quadratique',4.5,5,5.9,6.1,array['blanc','jaune','orangé','brun','gris']::text[],'blanc','vitreux à adamantin','transparent à translucide','distinct','subconchoïdale à irrégulière','Bipyramides pseudo-octaédriques, masses granulaires.','Bleu-blanc vive sous ultraviolets courts, utilisée pour la prospection nocturne.','Skarns, greisens, filons de quartz liés aux granites, pegmatites.','Dédiée au chimiste suédois Carl Wilhelm Scheele.',null,'Quartz et calcite : bien plus légers, sans fluorescence bleue. Sa densité est remarquable pour un minéral clair.','Minerai de tungstène, lourd, dont la fluorescence bleu-blanc sous UV courts est un outil de prospection.','published'),
('Apatite','apatite','Ca₅(PO₄)₃(F,Cl,OH)','Phosphates, arséniates et vanadates','Hexagonal',5,5,3.1,3.25,array['vert','bleu','jaune','violet','incolore','brun']::text[],'blanc','vitreux à résineux','transparent à opaque','indistinct','conchoïdale à irrégulière','Prismes hexagonaux, tablettes, masses granulaires.','Fréquente, de couleur variable.','Présente en petites quantités dans presque toutes les roches ; beaux cristaux dans les pegmatites, fentes alpines, skarns et carbonatites.','Du grec apatein, « tromper » : on la confondait avec d''autres minéraux.','Nom de groupe : la fluorapatite est l''espèce la plus courante ; hydroxylapatite (constituant des os et des dents).','Béryl : plus dur. Tourmaline : section triangulaire. Sert de référence de dureté 5.','Phosphate de calcium, référence de dureté 5 de l''échelle de Mohs, qui constitue aussi l''essentiel de nos os et de nos dents.','published'),
('Pyromorphite','pyromorphite','Pb₅(PO₄)₃Cl','Phosphates, arséniates et vanadates','Hexagonal',3.5,4,6.7,7.1,array['vert','jaune','brun','orange']::text[],'blanc','résineux à subadamantin','transparent à translucide','imparfait','subconchoïdale','Prismes hexagonaux, souvent en tonnelet ou creux, encroûtements.',null,'Zones d''oxydation des gisements de plomb. La mine des Farges (Corrèze) est célèbre pour ses pyromorphites vertes.','Du grec pyr, « feu », et morphê, « forme » : fondue, elle recristallise en perle facettée.',null,'Mimétite : même aspect, riche en arsenic (analyse). Apatite : bien plus légère.','Phosphate de plomb aux prismes hexagonaux vert vif, classique des gisements français.','published'),
('Mimétite','mimetite','Pb₅(AsO₄)₃Cl','Phosphates, arséniates et vanadates','Hexagonal',3.5,4,7.1,7.3,array['jaune','orange','brun','vert pâle','incolore']::text[],'blanc','résineux à subadamantin','transparent à translucide','imparfait','subconchoïdale','Prismes hexagonaux, formes en tonnelet (campylite), encroûtements botryoïdaux.',null,'Zones d''oxydation des gisements de plomb riches en arsenic.','Du grec mimetês, « imitateur », car elle ressemble à la pyromorphite.','Campylite (cristaux en tonnelet courbé).','Pyromorphite et vanadinite : même famille, analyse souvent nécessaire.','Arséniate de plomb, sosie de la pyromorphite, souvent jaune à orangé.','published'),
('Vanadinite','vanadinite','Pb₅(VO₄)₃Cl','Phosphates, arséniates et vanadates','Hexagonal',2.5,3,6.8,7.1,array['rouge orangé','brun rouge','jaune']::text[],'blanc à jaunâtre','résineux à subadamantin','transparent à opaque','aucun','conchoïdale à irrégulière','Prismes hexagonaux nets, parfois creux.',null,'Zones d''oxydation des gisements de plomb en climat aride (Mibladen, Maroc).','Du vanadium, qu''elle contient.','Endlichite (riche en arsenic).','Pyromorphite et mimétite : mêmes formes, couleurs différentes ; analyse en cas de doute.','Vanadate de plomb aux prismes hexagonaux rouge orangé, très populaire auprès des collectionneurs.','published'),
('Turquoise','turquoise','CuAl₆(PO₄)₄(OH)₈·4H₂O','Phosphates, arséniates et vanadates','Triclinique',5,6,2.6,2.9,array['bleu ciel','bleu vert','vert']::text[],'blanc à vert pâle','cireux à terne','opaque','aucun','conchoïdale','Masses, nodules, veinules ; cristaux microscopiques très rares.',null,'Altération de roches riches en aluminium et en cuivre, en climat aride.','De l''ancien français « pierre turquoise », car elle arrivait en Europe par la Turquie.',null,'Très souvent imitée : howlite ou magnésite teintes, plastique, turquoise « reconstituée » ou stabilisée à la résine.','Phosphate de cuivre et d''aluminium bleu ciel, gemme appréciée depuis l''Antiquité. Sensible à la chaleur, aux graisses et aux produits chimiques.','published'),
('Autunite','autunite','Ca(UO₂)₂(PO₄)₂·10–12H₂O','Phosphates, arséniates et vanadates','Quadratique',2,2.5,3.1,3.2,array['jaune citron','jaune vert']::text[],'jaune pâle','vitreux à nacré','transparent à translucide','parfait basal','irrégulière','Tablettes carrées minces, en éventails ou en rosettes.','Vert-jaune intense sous ultraviolets.','Zones d''oxydation des gisements d''uranium, granites et pegmatites altérés.','D''Autun (Saône-et-Loire), où elle fut décrite.',null,'Torbernite : verte, non fluorescente.','Phosphate d''uranium jaune vert, spectaculaire sous UV. Radioactive : à conserver dans une boîte fermée, à l''écart des lieux de vie. Se déshydrate à l''air sec.','published'),
('Torbernite','torbernite','Cu(UO₂)₂(PO₄)₂·8–12H₂O','Phosphates, arséniates et vanadates','Quadratique',2,2.5,3.22,3.22,array['vert émeraude']::text[],'vert pâle','vitreux à nacré','transparent à translucide','parfait basal','irrégulière','Tablettes carrées, souvent épaisses, en groupes.',null,'Zones d''oxydation des gisements d''uranium et de cuivre.','Dédiée au chimiste suédois Torbern Bergman.',null,'Autunite : jaune et fluorescente (le cuivre éteint la fluorescence de la torbernite).','Phosphate de cuivre et d''uranium vert émeraude. Radioactif. Perd de l''eau à l''air sec et devient de la métatorbernite.','published'),
('Vivianite','vivianite','Fe₃(PO₄)₂·8H₂O','Phosphates, arséniates et vanadates','Monoclinique',1.5,2,2.68,2.68,array['incolore (frais)','bleu','vert foncé','presque noir']::text[],'blanc bleuté, virant au bleu foncé','vitreux, nacré sur le clivage','transparent à translucide','parfait (une direction)','fibreuse','Prismes, lames flexibles, nodules, masses terreuses.',null,'Argiles, tourbières et sédiments riches en matière organique, fossiles, pegmatites et filons.','Dédiée au minéralogiste britannique John Henry Vivian.',null,'Sa couleur qui fonce à la lumière et son clivage parfait sont caractéristiques.','Phosphate de fer incolore à l''état frais, qui bleuit puis noircit à l''air et à la lumière : à conserver dans l''obscurité.','published'),
('Variscite','variscite','AlPO₄·2H₂O','Phosphates, arséniates et vanadates','Orthorhombique',3.5,4.5,2.57,2.57,array['vert pâle','vert pomme','bleu vert']::text[],'blanc','cireux à vitreux','translucide à opaque','bon (une direction)','conchoïdale à irrégulière','Nodules, veines, encroûtements ; cristaux très rares.',null,'Altération de roches riches en phosphates et en aluminium.','De Variscia, nom latin du Vogtland (Allemagne).',null,'Turquoise : plus dure, contient du cuivre. Chrysoprase : bien plus dure.','Phosphate d''aluminium vert tendre, taillé en cabochons comme la turquoise.','published'),
('Wavellite','wavellite','Al₃(PO₄)₂(OH,F)₃·5H₂O','Phosphates, arséniates et vanadates','Orthorhombique',3.5,4,2.36,2.36,array['vert','jaune','blanc','bleuté']::text[],'blanc','vitreux à nacré','translucide','parfait','subconchoïdale à irrégulière','Sphères et hémisphères fibro-radiés qui dessinent des étoiles sur les plans de fracture.',null,'Fissures de roches sédimentaires et métamorphiques de basse température riches en aluminium.','Dédiée au médecin britannique William Wavell.',null,'Ses rosettes rayonnantes en étoiles vertes sont caractéristiques.','Phosphate d''aluminium formant des étoiles fibreuses vertes à la surface des roches.','published'),
('Libéthénite','libethenite','Cu₂PO₄(OH)','Phosphates, arséniates et vanadates','Orthorhombique',4,4,3.97,3.97,array['vert olive sombre','vert noirâtre']::text[],'vert olive','vitreux','translucide','indistinct','conchoïdale à irrégulière','Petits prismes courts et bipyramides, encroûtements.',null,'Zones d''oxydation des gisements de cuivre.','De Libethen, aujourd''hui Ľubietová (Slovaquie).',null,'Olivénite : arséniate, aiguilles plus allongées. Malachite : effervescence.','Phosphate de cuivre vert sombre en petits cristaux brillants.','published'),
('Olivénite','olivenite','Cu₂AsO₄(OH)','Phosphates, arséniates et vanadates','Monoclinique',3,3,4.46,4.46,array['vert olive','brun','jaune paille']::text[],'vert olive à brun','adamantin à vitreux, soyeux pour les fibres','translucide à opaque','indistinct','conchoïdale','Aiguilles, prismes, masses fibreuses.',null,'Zones d''oxydation des gisements de cuivre riches en arsenic.','De sa couleur vert olive.',null,'Libéthénite : phosphate, cristaux plus trapus. Adamite : contient du zinc, souvent fluorescente.','Arséniate de cuivre vert olive, en aiguilles ou en fibres soyeuses.','published'),
('Adamite','adamite','Zn₂AsO₄(OH)','Phosphates, arséniates et vanadates','Orthorhombique',3.5,3.5,4.32,4.48,array['jaune','vert','incolore','violet']::text[],'blanc','vitreux','transparent à translucide','bon','subconchoïdale à irrégulière','Cristaux prismatiques en rosettes et en éventails, encroûtements.','Vert-jaune intense sous ultraviolets.','Zones d''oxydation des gisements de zinc riches en arsenic (Ojuela, Mexique).','Dédiée au minéralogiste français Gilbert-Joseph Adam.','Adamite cuprifère (verte) ; adamite manganésifère (violette).','Olivénite : vert olive, moins fluorescente. Smithsonite : effervescence.','Arséniate de zinc jaune vif, aux rosettes lumineuses sous lampe UV.','published'),
('Érythrite','erythrite','Co₃(AsO₄)₂·8H₂O','Phosphates, arséniates et vanadates','Monoclinique',1.5,2.5,3.06,3.06,array['rose','rouge pourpre']::text[],'rose pâle','vitreux, nacré sur le clivage','transparent à translucide','parfait (une direction)','irrégulière','Aiguilles, rosettes, encroûtements pulvérulents (« fleur de cobalt »).',null,'Altération des arséniures de cobalt (cobaltite, skutterudite).','Du grec erythros, « rouge ».',null,'Sa couleur rose à pourpre et son association aux minerais de cobalt la distinguent facilement.','Arséniate de cobalt rose, la « fleur de cobalt » qui guidait autrefois les mineurs vers le minerai.','published'),
('Monazite','monazite','(Ce,La,Nd,Th)PO₄','Phosphates, arséniates et vanadates','Monoclinique',5,5.5,4.6,5.4,array['brun rougeâtre','jaune','brun']::text[],'blanc','résineux à vitreux','translucide à opaque','distinct','conchoïdale à irrégulière','Petits cristaux tabulaires, grains ; concentrée dans les sables.',null,'Granites, pegmatites, gneiss ; concentrée dans les sables de plage et de rivière.','Du grec monazein, « être solitaire », en raison de ses cristaux isolés.','Plusieurs espèces selon la terre rare dominante : monazite-(Ce), monazite-(La), monazite-(Nd).','Zircon : plus dur. Titanite : autre forme cristalline.','Phosphate de terres rares, souvent faiblement radioactif (thorium), utilisé pour dater les roches.','published'),
('Lazulite','lazulite','MgAl₂(PO₄)₂(OH)₂','Phosphates, arséniates et vanadates','Monoclinique',5.5,6,3.12,3.24,array['bleu azur','bleu profond']::text[],'blanc','vitreux','transparent à opaque','indistinct','irrégulière','Bipyramides aiguës, grains, masses.',null,'Quartzites et roches métamorphiques riches en aluminium, pegmatites.','Du persan lazhward, « bleu ».',null,'Lazurite (lapis-lazuli) : autre minéral, souvent associé à la pyrite. Azurite : bien plus tendre, effervescence.','Phosphate bleu azur, à ne pas confondre avec la lazurite du lapis-lazuli malgré la ressemblance des noms.','published'),
('Olivine','olivine','(Mg,Fe)₂SiO₄','Silicates (nésosilicates)','Orthorhombique',6.5,7,3.2,4.4,array['vert olive','jaune vert','brun']::text[],'blanc','vitreux','transparent à translucide','imparfait','conchoïdale','Grains, masses granulaires, nodules de péridotite dans les basaltes ; cristaux rares.',null,'Constituant majeur du manteau terrestre (péridotites), basaltes et gabbros ; fréquente en nodules dans les basaltes du Massif central.','De sa couleur vert olive.','Nom de série entre la forstérite (magnésium) et la fayalite (fer) ; péridot (qualité gemme).','Épidote : vert plus sombre, clivage parfait. Diopside : deux clivages nets.','Silicate vert olive, l''un des minéraux les plus abondants de la planète puisqu''il compose l''essentiel du manteau supérieur.','published'),
('Almandin','almandin','Fe₃Al₂(SiO₄)₃','Silicates (nésosilicates)','Cubique',7,7.5,4.1,4.3,array['rouge sombre','rouge violacé','brun']::text[],'blanc','vitreux à résineux','transparent à translucide','aucun','conchoïdale à irrégulière','Rhombododécaèdres, icositétraèdres, grains.',null,'Micaschistes et gneiss (métamorphisme régional), granites, alluvions.','D''Alabanda, ville antique d''Asie Mineure où l''on taillait les grenats.','Membre du groupe des grenats ; forme des séries avec le pyrope et la spessartine.','Pyrope : rouge plus vif, moins dense. Spinelle : octaèdres.','Le grenat le plus courant, rouge sombre, en cristaux à douze faces losangiques bien formés dans les micaschistes.','published'),
('Pyrope','pyrope','Mg₃Al₂(SiO₄)₃','Silicates (nésosilicates)','Cubique',7,7.5,3.5,3.8,array['rouge sang','rouge foncé','violacé']::text[],'blanc','vitreux','transparent','aucun','conchoïdale','Grains arrondis, rarement cristaux nets.',null,'Péridotites, kimberlites (indicateur de diamants), éclogites, alluvions.','Du grec pyropos, « ardent comme le feu ».','Grenat de Bohême ; rhodolite (intermédiaire pyrope–almandin, rose violacé).','Almandin : plus sombre et plus dense. Rubis : plus dur, trigonal.','Grenat rouge sang des roches profondes, dont la présence guide les prospecteurs de diamants.','published'),
('Grossulaire','grossulaire','Ca₃Al₂(SiO₄)₃','Silicates (nésosilicates)','Cubique',6.5,7.5,3.57,3.67,array['vert','jaune','orange','brun','rose','incolore']::text[],'blanc','vitreux à résineux','transparent à translucide','aucun','conchoïdale à irrégulière','Rhombododécaèdres, icositétraèdres, masses.',null,'Skarns et marbres (métamorphisme de contact de calcaires impurs), rodingites.','Du latin grossularia, « groseille à maquereau », pour la couleur de certains cristaux verts.','Hessonite (orange brun), tsavorite (verte, au vanadium), grossulaire massif (« jade du Transvaal »).','Andradite : plus dense, souvent plus sombre. Vésuvianite : forme quadratique.','Grenat calcique aux couleurs très variées, fréquent dans les skarns et les marbres.','published'),
('Andradite','andradite','Ca₃Fe₂(SiO₄)₃','Silicates (nésosilicates)','Cubique',6.5,7,3.8,3.9,array['brun','noir','vert','jaune']::text[],'blanc','vitreux à adamantin','transparent à opaque','aucun','conchoïdale à irrégulière','Rhombododécaèdres, souvent brillants et zonés.',null,'Skarns, serpentinites (démantoïde), roches alcalines (mélanite).','Dédiée au minéralogiste et homme d''État brésilien José Bonifácio de Andrada e Silva.','Démantoïde (vert, dispersion plus forte que le diamant), mélanite (noire, riche en titane), topazolite (jaune).','Grossulaire : moins dense. Mélanite et schorl : la tourmaline a une section triangulaire.','Grenat calcique et ferrifère, dont la variété démantoïde est l''une des gemmes les plus « feu » qui soient.','published'),
('Spessartine','spessartine','Mn₃Al₂(SiO₄)₃','Silicates (nésosilicates)','Cubique',6.5,7.5,4.12,4.18,array['orange','rouge brun','jaune orangé']::text[],'blanc','vitreux','transparent à translucide','aucun','conchoïdale','Rhombododécaèdres, icositétraèdres.',null,'Pegmatites et granites, rhyolites, roches métamorphiques riches en manganèse.','Du Spessart (Bavière, Allemagne).','Grenat « mandarine » (orange vif).','Hessonite (grossulaire) : moins dense. Almandin : plus rouge, plus sombre.','Grenat manganésifère orange, souvent sur matrice de quartz ou de feldspath dans les pegmatites.','published'),
('Uvarovite','uvarovite','Ca₃Cr₂(SiO₄)₃','Silicates (nésosilicates)','Cubique',6.5,7.5,3.59,3.9,array['vert émeraude']::text[],'blanc','vitreux','transparent à translucide','aucun','conchoïdale à irrégulière','Petits cristaux dodécaédriques en druses scintillantes.',null,'Serpentinites et gisements de chromite, skarns à chrome.','Dédiée au comte Sergueï Ouvarov, président de l''Académie des sciences de Russie.',null,'Démantoïde (andradite) : cristaux isolés, plus gros. Émeraude : hexagonale.','Le seul grenat toujours vert émeraude, en druses de minuscules cristaux étincelants.','published'),
('Zircon','zircon','ZrSiO₄','Silicates (nésosilicates)','Quadratique',7.5,7.5,4.6,4.7,array['brun','rouge','jaune','incolore','vert','bleu (chauffé)']::text[],'blanc','adamantin à vitreux','transparent à opaque','indistinct','conchoïdale','Prismes courts à terminaisons bipyramidales, grains roulés.','Parfois jaune ou orangée.','Granites, syénites, pegmatites, basaltes alcalins ; très résistant, concentré dans les alluvions.','Du persan zargun, « couleur d''or ».','Hyacinthe (rouge orangé) ; zircon « métamicte » (structure détruite par la radioactivité interne).','Diamant : bien plus dur. Cassitérite : plus dense. Vésuvianite : moins brillante.','Silicate de zirconium très résistant. Certains grains d''Australie, datés d''environ 4,4 milliards d''années, sont les plus anciens fragments connus de la croûte terrestre.','published'),
('Topaze','topaze','Al₂SiO₄(F,OH)₂','Silicates (nésosilicates)','Orthorhombique',8,8,3.49,3.57,array['incolore','jaune','bleu','rose','brun','orange (impériale)']::text[],'blanc','vitreux','transparent','parfait basal','subconchoïdale à irrégulière','Prismes striés en longueur à section losangique, terminaisons variées.','Parfois jaune ou verdâtre.','Pegmatites, greisens, cavités de rhyolites.','Traditionnellement rapporté à l''île Topazios, en mer Rouge.','Topaze impériale (orange rosé) ; les topazes bleu vif du commerce sont presque toujours irradiées puis chauffées.','Citrine (quartz jaune), souvent vendue abusivement comme « topaze » : pas de clivage, moins dense. Béryl : section hexagonale.','Référence de dureté 8 de l''échelle de Mohs. Son clivage basal parfait la rend pourtant sensible aux chocs.','published'),
('Andalousite','andalousite','Al₂SiO₅','Silicates (nésosilicates)','Orthorhombique',6.5,7.5,3.13,3.21,array['rose','brun rouge','vert','gris']::text[],'blanc','vitreux','transparent à opaque','bon (deux directions)','irrégulière à subconchoïdale','Prismes à section presque carrée ; chiastolite montrant une croix sombre en section.',null,'Métamorphisme de contact des schistes argileux (cornéennes), métamorphisme de basse pression.','D''Andalousie (Espagne).','Chiastolite (inclusions de carbone dessinant une croix).','Disthène et sillimanite, ses polymorphes : formes et duretés différentes.','Polymorphe du disthène et de la sillimanite, typique du métamorphisme de basse pression ; la chiastolite montre une croix noire en section.','published'),
('Disthène','disthene','Al₂SiO₅','Silicates (nésosilicates)','Triclinique',4.5,7,3.53,3.67,array['bleu','blanc','gris','vert','noir']::text[],'blanc','vitreux, nacré sur le clivage','transparent à translucide','parfait (une direction)','irrégulière','Lames allongées, souvent bleues au centre, agrégats rayonnants.',null,'Micaschistes, gneiss et éclogites (métamorphisme de haute pression), pegmatites.','Du grec dis, « deux fois », et sthenos, « force » : sa dureté varie selon la direction. Aussi appelé cyanite (kyanite).',null,'Ses lames bleues qui se rayent au couteau dans la longueur mais pas en travers sont uniques.','Polymorphe de l''andalousite et de la sillimanite, célèbre pour sa dureté anisotrope : 4,5 à 5 le long des lames, 6,5 à 7 en travers.','published'),
('Sillimanite','sillimanite','Al₂SiO₅','Silicates (nésosilicates)','Orthorhombique',6.5,7.5,3.23,3.27,array['blanc','gris','brun','vert pâle']::text[],'blanc','vitreux à soyeux','transparent à translucide','parfait (une direction)','irrégulière','Prismes allongés, fibres (fibrolite), masses fibreuses.',null,'Gneiss et micaschistes de métamorphisme de haute température.','Dédiée au chimiste américain Benjamin Silliman.','Fibrolite (fibreuse).','Trémolite fibreuse : clivages à 124°. Disthène : lames bleutées.','Polymorphe de haute température de l''andalousite et du disthène, souvent en fines fibres.','published'),
('Staurotide','staurotide','(Fe,Mg)₂Al₉Si₄O₂₃(OH)','Silicates (nésosilicates)','Monoclinique',7,7.5,3.74,3.83,array['brun rouge','brun','noir']::text[],'blanc à grisâtre','vitreux à résineux','translucide à opaque','distinct','subconchoïdale','Prismes, macles en croix à angle droit ou à 60° (« croisettes »).',null,'Micaschistes et gneiss de métamorphisme moyen, souvent avec grenat et disthène.','Du grec stauros, « croix ». Aussi appelée staurolite.',null,'Andalousite (chiastolite) : croix interne visible en section, pas une macle.','Silicate brun dont les macles en croix, les « croisettes » ou « pierres de croix », sont célèbres en Bretagne.','published'),
('Titanite','titanite','CaTiSiO₅','Silicates (nésosilicates)','Monoclinique',5,5.5,3.48,3.6,array['jaune','vert','brun','noir']::text[],'blanc','adamantin à résineux','transparent à opaque','distinct','conchoïdale','Cristaux cunéiformes en « enveloppe », macles.',null,'Syénites, granites, roches métamorphiques, fentes alpines.','Du titane, qu''elle contient. Ancien nom : sphène, du grec sphên, « coin ».',null,'Sa forme en coin et sa forte dispersion (feux) la distinguent.','Silicate de calcium et de titane aux cristaux en forme d''enveloppe, à la dispersion supérieure à celle du diamant.','published'),
('Datolite','datolite','CaBSiO₄(OH)','Silicates (nésosilicates)','Monoclinique',5,5.5,2.96,3,array['incolore','blanc','vert pâle','jaune pâle']::text[],'blanc','vitreux','transparent à translucide','aucun','conchoïdale à irrégulière','Prismes courts aux faces multiples, nodules porcelanés.',null,'Cavités des basaltes et diabases, avec zéolites et prehnite ; skarns.','Du grec dateisthai, « diviser », pour sa texture granulaire.',null,'Quartz : plus dur. Apophyllite : clivage basal parfait.','Borosilicate de calcium aux cristaux vitreux très facettés, fréquent dans les basaltes avec les zéolites.','published'),
('Épidote','epidote','Ca₂(Al₂Fe³⁺)(Si₂O₇)(SiO₄)O(OH)','Silicates (sorosilicates)','Monoclinique',6,7,3.38,3.49,array['vert pistache','vert noirâtre','jaune vert']::text[],'blanc à gris','vitreux','transparent à opaque','parfait (une direction)','irrégulière','Prismes striés allongés, gerbes, masses granulaires.',null,'Roches métamorphiques (schistes verts), fentes alpines, skarns, altération hydrothermale.','Du grec epidosis, « accroissement » : une face du prisme est plus développée que l''autre.',null,'Actinote : clivages à 124°, plus fibreuse. Tourmaline : section triangulaire.','Silicate vert pistache aux prismes striés, fortement pléochroïque (sa couleur change selon l''angle d''observation).','published'),
('Zoïsite','zoisite','Ca₂Al₃(Si₂O₇)(SiO₄)O(OH)','Silicates (sorosilicates)','Orthorhombique',6,7,3.15,3.36,array['gris','vert','rose (thulite)','bleu violet (tanzanite)']::text[],'blanc','vitreux','transparent à translucide','parfait (une direction)','irrégulière','Prismes striés, masses.',null,'Roches métamorphiques, éclogites, altération des plagioclases.','Dédiée au naturaliste slovène Sigmund Zois.','Tanzanite (bleu violet, le plus souvent chauffée), thulite (rose), anyolite (verte, avec rubis).','Épidote : vert plus jaune. Clinozoïsite : polymorphe monoclinique.','Silicate dont la variété tanzanite, découverte en Tanzanie dans les années 1960, est devenue une gemme célèbre.','published'),
('Vésuvianite','vesuvianite','Ca₁₀(Mg,Fe)₂Al₄(SiO₄)₅(Si₂O₇)₂(OH,F)₄','Silicates (sorosilicates)','Quadratique',6,7,3.32,3.43,array['brun','vert','jaune','violet']::text[],'blanc','vitreux à résineux','transparent à translucide','indistinct','subconchoïdale à irrégulière','Prismes à section carrée, masses.',null,'Skarns et marbres (métamorphisme de contact), rodingites.','Du Vésuve, où elle fut décrite. Ancien nom : idocrase.','Californite (massive verte, imitant le jade).','Grenat : cubique. Zircon : plus dense, plus brillant.','Silicate complexe aux prismes à section carrée, typique des marbres et des skarns.','published'),
('Hémimorphite','hemimorphite','Zn₄Si₂O₇(OH)₂·H₂O','Silicates (sorosilicates)','Orthorhombique',4.5,5,3.4,3.5,array['incolore','blanc','bleu pâle','vert pâle']::text[],'blanc','vitreux','transparent à translucide','parfait','conchoïdale à irrégulière','Lames en éventails, mamelons, crêtes ; cristaux aux deux extrémités différentes.',null,'Zones d''oxydation des gisements de zinc.','De l''hémimorphisme : ses cristaux n''ont pas la même forme aux deux extrémités.','Ancien nom : calamine (partagé avec la smithsonite).','Smithsonite : fait effervescence. Calcédoine : bien plus dure.','Silicate de zinc en éventails de lames incolores ou en mamelons bleu pâle. Pyroélectrique.','published'),
('Axinite','axinite','Ca₂(Fe,Mn,Mg)Al₂BSi₄O₁₅(OH)','Silicates (sorosilicates)','Triclinique',6.5,7,3.18,3.37,array['brun violacé','brun','gris','jaune (manganèse)']::text[],'blanc','vitreux','transparent à translucide','bon (une direction)','conchoïdale à irrégulière','Cristaux aplatis aux arêtes tranchantes comme une lame de hache.',null,'Fentes alpines, skarns, zones de contact des granites. Le Bourg-d''Oisans (Isère) en a livré des cristaux réputés.','Du grec axinê, « hache ».','Nom de groupe : axinite-(Fe), axinite-(Mn), axinite-(Mg), tinzenite.','Sa forme en lame tranchante et sa couleur brun violacé sont caractéristiques.','Borosilicate aux cristaux tranchants en forme de hache, classique des fentes alpines.','published'),
('Béryl','beryl','Be₃Al₂Si₆O₁₈','Silicates (cyclosilicates)','Hexagonal',7.5,8,2.63,2.92,array['vert','bleu','jaune','rose','incolore','blanc']::text[],'blanc','vitreux','transparent à opaque','imparfait basal','conchoïdale à irrégulière','Prismes hexagonaux, parfois géants, terminés par une face plane.',null,'Pegmatites et granites ; micaschistes et filons pour l''émeraude.','Du grec bêryllos, désignant les pierres vert de mer.','Émeraude (vert, chrome ou vanadium), aigue-marine (bleu), héliodore (jaune), morganite (rose), goshénite (incolore), béryl rouge (bixbite).','Apatite : moins dure. Quartz : terminaison pointue. Topaze : clivage parfait.','Silicate de béryllium aux prismes hexagonaux, dont les variétés gemmes sont l''émeraude et l''aigue-marine.','published'),
('Schorl','schorl','NaFe₃Al₆(Si₆O₁₈)(BO₃)₃(OH)₃(OH)','Silicates (cyclosilicates)','Trigonal',7,7,3.18,3.22,array['noir']::text[],'blanc à gris bleuté','vitreux','opaque','très indistinct','conchoïdale à irrégulière','Prismes striés en longueur, à section triangulaire bombée ; aiguilles rayonnantes.',null,'Granites, pegmatites, greisens, roches métamorphiques.','De l''allemand Schörl, vieux nom d''origine incertaine, peut-être tiré d''un village de Saxe.','Tourmaline noire, la plus commune du groupe des tourmalines.','Hornblende : deux clivages à 124°, section non triangulaire. Augite : clivages à 90°.','Tourmaline noire, la plus fréquente, en prismes striés à section triangulaire. Piézoélectrique et pyroélectrique.','published'),
('Elbaïte','elbaite','Na(Li₁,₅Al₁,₅)Al₆(Si₆O₁₈)(BO₃)₃(OH)₃(OH)','Silicates (cyclosilicates)','Trigonal',7.5,7.5,2.9,3.1,array['vert','rose','rouge','bleu','multicolore','incolore']::text[],'blanc','vitreux','transparent à translucide','très indistinct','conchoïdale à irrégulière','Prismes striés à section triangulaire, souvent zonés en couleur.',null,'Pegmatites granitiques riches en lithium.','De l''île d''Elbe (Italie).','Rubellite (rose à rouge), indicolite (bleue), verdelite (verte), tourmaline « melon d''eau » (cœur rose, écorce verte).','Béryl : section hexagonale. Topaze : clivage basal parfait.','Tourmaline gemme au lithium, aux couleurs vives souvent disposées en zones.','published'),
('Dravite','dravite','NaMg₃Al₆(Si₆O₁₈)(BO₃)₃(OH)₃(OH)','Silicates (cyclosilicates)','Trigonal',7,7.5,3.03,3.18,array['brun','brun noir','jaune brun']::text[],'blanc à brun clair','vitreux','transparent à opaque','très indistinct','conchoïdale à irrégulière','Prismes courts à section triangulaire.',null,'Marbres et roches métamorphiques magnésiennes.','De la région de la Drave (Carinthie, Autriche).',null,'Schorl : noir, riche en fer. Vésuvianite : section carrée.','Tourmaline magnésienne brune, typique des marbres.','published'),
('Cordiérite','cordierite','Mg₂Al₄Si₅O₁₈','Silicates (cyclosilicates)','Orthorhombique',7,7.5,2.57,2.66,array['bleu violet','gris','jaunâtre']::text[],'blanc','vitreux','transparent à translucide','médiocre','conchoïdale','Prismes courts pseudo-hexagonaux, grains, masses.',null,'Roches métamorphiques de haute température et basse pression (cornéennes, gneiss), granites.','Dédiée au géologue français Pierre Louis Antoine Cordier.','Iolite (gemme), parfois appelée « pierre des Vikings ».','Quartz : pas de pléochroïsme. Saphir : bien plus dur et dense.','Silicate au pléochroïsme spectaculaire : bleu violet, gris ou jaune pâle selon l''angle de vue.','published'),
('Dioptase','dioptase','CuSiO₃·H₂O','Silicates (cyclosilicates)','Trigonal',5,5,3.28,3.35,array['vert émeraude intense']::text[],'vert pâle','vitreux à adamantin','transparent à translucide','parfait rhomboédrique','conchoïdale à irrégulière','Prismes courts terminés par des rhomboèdres, druses.',null,'Zones d''oxydation des gisements de cuivre en climat aride (Namibie, Congo, Kazakhstan).','Du grec dia, « à travers », et optos, « visible » : on voit ses clivages par transparence.',null,'Émeraude : bien plus dure, sans clivage. Malachite : opaque, effervescence.','Silicate de cuivre d''un vert émeraude profond, fragile en raison de son clivage parfait.','published'),
('Augite','augite','(Ca,Mg,Fe)₂(Si,Al)₂O₆','Silicates (inosilicates)','Monoclinique',5.5,6,3.19,3.56,array['noir','vert foncé','brun']::text[],'blanc grisâtre à vert gris','vitreux','translucide à opaque','bon, deux directions presque à angle droit (87°)','irrégulière à conchoïdale','Prismes trapus à section octogonale, macles, grains.',null,'Basaltes, andésites, gabbros ; fréquente en cristaux dans les scories et tufs volcaniques du Massif central.','Du grec augê, « éclat ».',null,'Hornblende : clivages à 124° et 56°. Schorl : section triangulaire.','Pyroxène noir le plus commun, en cristaux trapus aux clivages presque perpendiculaires.','published'),
('Diopside','diopside','CaMgSi₂O₆','Silicates (inosilicates)','Monoclinique',5.5,6.5,3.22,3.38,array['vert clair à vert foncé','incolore','brun']::text[],'blanc à vert pâle','vitreux','transparent à translucide','bon, deux directions à environ 87°','irrégulière','Prismes courts, grains, masses.',null,'Skarns et marbres, péridotites, roches métamorphiques calciques.','Du grec dis, « deux », et opsis, « vue », en raison de ses deux aspects possibles.','Diopside chromifère (vert vif), violane (bleu violet).','Olivine : sans clivage net. Épidote : un seul clivage parfait.','Pyroxène calcique et magnésien, vert clair, fréquent dans les marbres.','published'),
('Jadéite','jadeite','NaAlSi₂O₆','Silicates (inosilicates)','Monoclinique',6,7,3.24,3.43,array['vert','blanc','lavande','gris','noir']::text[],'blanc','vitreux à cireux','translucide à opaque','bon (deux directions)','esquilleuse','Masses à grain fin, feutrées et très tenaces.',null,'Roches métamorphiques de haute pression et basse température, liées aux zones de subduction (Myanmar, Guatemala).','De « jade », de l''espagnol piedra de ijada, « pierre du flanc », à laquelle on prêtait des vertus contre les coliques néphrétiques.','Le « jade » désigne soit la jadéite (jade impérial), soit la néphrite (amphibole).','Néphrite : légèrement plus tendre et moins dense. Serpentine et calcédoine teinte : imitations fréquentes.','Pyroxène sodique qui forme, en masses feutrées extraordinairement tenaces, le jade le plus précieux.','published'),
('Spodumène','spodumene','LiAlSi₂O₆','Silicates (inosilicates)','Monoclinique',6.5,7,3.03,3.23,array['incolore','gris','rose lilas (kunzite)','vert (hiddénite)','jaune']::text[],'blanc','vitreux','transparent à translucide','parfait, deux directions à environ 87°','irrégulière à subconchoïdale','Grands prismes aplatis et striés.','Rose à orangée pour la kunzite, parfois phosphorescente.','Pegmatites granitiques riches en lithium.','Du grec spodoumenos, « réduit en cendres », pour l''aspect gris de ses masses.','Kunzite (rose lilas), hiddénite (verte).','Topaze : un seul clivage. Béryl : section hexagonale.','Pyroxène au lithium, important minerai de ce métal, dont la kunzite rose pâlit à la lumière du soleil.','published'),
('Aegyrine','aegyrine','NaFe³⁺Si₂O₆','Silicates (inosilicates)','Monoclinique',6,6,3.5,3.6,array['vert sombre','noir','brun vert']::text[],'vert jaunâtre pâle','vitreux','translucide à opaque','bon, deux directions à environ 87°','irrégulière','Longs prismes à terminaison aiguë, aiguilles.',null,'Syénites néphéliniques, pegmatites alcalines, carbonatites.','D''Ægir, dieu scandinave de la mer, car elle fut décrite en Norvège.',null,'Schorl : section triangulaire. Hornblende : clivages à 124°.','Pyroxène sodique aux longs prismes noirs pointus, typique des roches alcalines.','published'),
('Rhodonite','rhodonite','CaMn₄Si₅O₁₅','Silicates (inosilicates)','Triclinique',5.5,6.5,3.57,3.76,array['rose','rouge','rouge brun (veines noires)']::text[],'blanc','vitreux','transparent à opaque','parfait, deux directions à environ 92°','conchoïdale à irrégulière','Masses granulaires veinées de noir, cristaux tabulaires rares.',null,'Gisements métamorphiques de manganèse, skarns, filons hydrothermaux.','Du grec rhodon, « rose ».',null,'Rhodochrosite : plus tendre, fait effervescence à l''acide, sans veines noires.','Silicate de manganèse rose, souvent veiné d''oxydes noirs, taillé en objets ornementaux.','published'),
('Wollastonite','wollastonite','CaSiO₃','Silicates (inosilicates)','Triclinique',4.5,5,2.86,3.09,array['blanc','gris','incolore']::text[],'blanc','vitreux à soyeux','transparent à translucide','parfait (une direction)','esquilleuse','Masses fibreuses ou lamellaires rayonnantes.','Parfois jaune ou orangée.','Marbres et skarns (métamorphisme de contact de calcaires siliceux).','Dédiée au chimiste et physicien britannique William Hyde Wollaston.',null,'Trémolite : clivages à 124°. Pectolite : aiguilles plus fines.','Silicate de calcium blanc en fibres ou en lamelles rayonnantes, formé au contact du calcaire et du magma.','published'),
('Trémolite','tremolite','Ca₂Mg₅Si₈O₂₂(OH)₂','Silicates (inosilicates)','Monoclinique',5,6,2.99,3.03,array['blanc','gris','vert pâle','incolore']::text[],'blanc','vitreux à soyeux','transparent à translucide','parfait, deux directions à 56° et 124°','esquilleuse','Prismes, lames, fibres et masses fibreuses.',null,'Marbres dolomitiques et roches métamorphiques magnésiennes.','Du Val Tremola (Suisse).','Néphrite (jade, en masses feutrées tenaces, avec l''actinote) ; hexagonite (rose violacé).','Wollastonite : pas de clivage à 124°. Actinote : plus verte (plus riche en fer).','Amphibole claire. Ses variétés fibreuses sont une forme d''amiante : ne pas gratter, ne pas respirer les poussières.','published'),
('Actinote','actinote','Ca₂(Mg,Fe)₅Si₈O₂₂(OH)₂','Silicates (inosilicates)','Monoclinique',5,6,3.03,3.24,array['vert','vert foncé','vert grisâtre']::text[],'blanc','vitreux à soyeux','transparent à translucide','parfait, deux directions à 56° et 124°','esquilleuse','Prismes aciculaires en gerbes rayonnantes, fibres.',null,'Schistes verts, amphibolites, roches métamorphiques de basse à moyenne température.','Du grec aktis, « rayon », pour ses cristaux rayonnants. Aussi appelée actinolite.','Néphrite (jade), byssolite (fibres fines).','Épidote : vert pistache, un seul clivage. Trémolite : plus claire.','Amphibole verte en aiguilles rayonnantes. Les variétés fibreuses (amiante) demandent des précautions.','published'),
('Hornblende','hornblende','Ca₂(Mg,Fe,Al)₅(Si,Al)₈O₂₂(OH)₂','Silicates (inosilicates)','Monoclinique',5,6,3,3.5,array['noir','vert foncé','brun']::text[],'blanc grisâtre à vert gris','vitreux','translucide à opaque','parfait, deux directions à 56° et 124°','irrégulière','Prismes allongés à section losangique ou hexagonale, grains.',null,'Granites, diorites, andésites, amphibolites et gneiss.','De l''allemand Horn, « corne », et blenden, « éblouir, tromper ».','Nom générique pour les amphiboles calciques sombres (magnésio-hornblende, ferro-hornblende…).','Augite : clivages presque à angle droit. Schorl : section triangulaire, sans clivage.','Amphibole sombre très commune ; ses deux clivages à 124° la distinguent des pyroxènes.','published'),
('Glaucophane','glaucophane','Na₂(Mg₃Al₂)Si₈O₂₂(OH)₂','Silicates (inosilicates)','Monoclinique',5,6,3,3.15,array['bleu gris','bleu lavande','bleu noir']::text[],'gris bleuté','vitreux','translucide','bon, deux directions à 56° et 124°','conchoïdale à irrégulière','Prismes, aiguilles, masses fibreuses.',null,'Schistes bleus (métamorphisme de haute pression et basse température) ; l''île de Groix (Morbihan) en est un exemple classique.','Du grec glaukos, « bleu-vert », et phainesthai, « paraître ».',null,'Disthène : un seul clivage, lames. Riebeckite : plus sombre.','Amphibole bleue, marqueur des anciennes zones de subduction, qui donne leur couleur aux schistes bleus.','published'),
('Prehnite','prehnite','Ca₂Al₂Si₃O₁₀(OH)₂','Silicates (inosilicates)','Orthorhombique',6,6.5,2.8,2.95,array['vert pâle','vert jaune','blanc','gris']::text[],'blanc','vitreux à nacré','transparent à translucide','bon (une direction)','irrégulière','Mamelons, sphères et crêtes aux cristaux tabulaires accolés.',null,'Cavités des basaltes et diabases, avec zéolites ; roches métamorphiques de bas degré.','Dédiée au colonel néerlandais Hendrik von Prehn.',null,'Calcédoine : plus dure, sans éclat nacré. Smithsonite : effervescence.','Silicate vert pâle en mamelons translucides, fréquent avec les zéolites des basaltes.','published'),
('Muscovite','muscovite','KAl₂(AlSi₃O₁₀)(OH)₂','Silicates (phyllosilicates)','Monoclinique',2,2.5,2.77,2.88,array['incolore','argenté','brun clair','vert pâle']::text[],'blanc','vitreux à nacré','transparent à translucide','parfait basal (feuillets élastiques)','écailleuse','Feuillets et « livres » pseudo-hexagonaux, paillettes, masses écailleuses.',null,'Granites, pegmatites (parfois en grandes plaques), micaschistes et gneiss.','Du « verre de Moscovie » : ses grandes feuilles servaient de vitres.','Séricite (en fines paillettes soyeuses), fuchsite (verte, au chrome).','Biotite : noire. Talc et gypse : feuillets non élastiques.','Mica blanc dont les feuillets transparents, souples et élastiques se détachent à l''ongle.','published'),
('Biotite','biotite','K(Mg,Fe)₃(AlSi₃O₁₀)(OH,F)₂','Silicates (phyllosilicates)','Monoclinique',2.5,3,2.7,3.4,array['noir','brun foncé','vert foncé']::text[],'blanc à gris','vitreux à submétallique','translucide à opaque','parfait basal (feuillets élastiques)','écailleuse','Paillettes, feuillets pseudo-hexagonaux, masses écailleuses.',null,'Granites, diorites, roches volcaniques, gneiss et micaschistes.','Dédiée au physicien français Jean-Baptiste Biot.','Nom de série (annite–phlogopite) plutôt qu''espèce pour l''IMA. Altérée, elle prend un reflet doré trompeur.','Muscovite : claire. Phlogopite : plus claire, brun cuivré. Les paillettes dorées de biotite altérée sont souvent prises pour de l''or.','Mica noir très répandu dans les granites, aux feuillets élastiques.','published'),
('Phlogopite','phlogopite','KMg₃(AlSi₃O₁₀)(F,OH)₂','Silicates (phyllosilicates)','Monoclinique',2,2.5,2.78,2.85,array['brun jaune','brun cuivré','vert','incolore']::text[],'blanc','nacré à submétallique','transparent à translucide','parfait basal (feuillets élastiques)','écailleuse','Prismes pseudo-hexagonaux, feuillets.',null,'Marbres, péridotites, kimberlites, carbonatites.','Du grec phlogopos, « semblable au feu », pour son reflet cuivré.',null,'Biotite : plus sombre (plus riche en fer). Muscovite : incolore.','Mica magnésien brun cuivré, typique des marbres et des roches ultrabasiques.','published'),
('Lépidolite','lepidolite','K(Li,Al)₃(Si,Al)₄O₁₀(F,OH)₂','Silicates (phyllosilicates)','Monoclinique',2.5,3,2.8,2.9,array['lilas','rose','violet','gris']::text[],'blanc','nacré à vitreux','translucide','parfait basal','écailleuse','Masses écailleuses, feuillets, « livres » hexagonaux.',null,'Pegmatites granitiques riches en lithium, avec elbaïte et spodumène.','Du grec lepidos, « écaille ».','Nom de série (polylithionite–trilithionite).','Muscovite rose : moins violette. Sa couleur lilas et son association à la tourmaline rose aident à la reconnaître.','Mica au lithium lilas, souvent en masses écailleuses scintillantes.','published'),
('Talc','talc','Mg₃Si₄O₁₀(OH)₂','Silicates (phyllosilicates)','Monoclinique',1,1,2.58,2.83,array['blanc','vert pâle','gris','brunâtre']::text[],'blanc','nacré à gras','translucide','parfait basal','irrégulière','Masses foliées, écailleuses ou compactes (stéatite).',null,'Altération hydrothermale et métamorphisme des roches magnésiennes (serpentinites, dolomies). La carrière de Trimouns (Ariège) est l''une des plus grandes au monde.','De l''arabe talq.','Stéatite ou « pierre à savon » (massive, sculptable).','Pyrophyllite : très semblable (analyse). Gypse : un peu plus dur, soluble.','Minéral le plus tendre de l''échelle de Mohs (1) : il se raye à l''ongle et a un toucher savonneux.','published'),
('Clinochlore','clinochlore','(Mg,Fe)₅Al(Si₃Al)O₁₀(OH)₈','Silicates (phyllosilicates)','Monoclinique',2,2.5,2.6,3.02,array['vert','vert foncé','blanc','rose (kämmererite)']::text[],'vert pâle à blanc','nacré à gras','transparent à translucide','parfait basal (lamelles flexibles, non élastiques)','écailleuse','Tablettes pseudo-hexagonales, écailles, masses.',null,'Schistes verts, serpentinites, fentes alpines, altération des minéraux ferromagnésiens.','Du grec klinein, « incliner », et chloros, « vert ».','Membre le plus commun du groupe des chlorites ; kämmererite (violacée, au chrome).','Micas : lamelles élastiques. Talc : plus tendre, blanc.','La plus courante des chlorites, qui colore en vert de nombreuses roches métamorphiques.','published'),
('Serpentine','serpentine','Mg₃Si₂O₅(OH)₄','Silicates (phyllosilicates)','Monoclinique',2.5,4,2.5,2.6,array['vert clair à vert foncé','jaune vert','noir']::text[],'blanc','gras, cireux ou soyeux','translucide à opaque','variable','conchoïdale à esquilleuse','Masses compactes, veinules fibreuses (chrysotile), lames (antigorite).',null,'Altération des péridotites et dunites (serpentinites), marbres.','Du latin serpens, « serpent », pour l''aspect tacheté des serpentinites.','Nom de groupe : antigorite, lizardite, chrysotile (fibreux, principale forme d''amiante).','Jade : plus dur et plus tenace. Calcédoine verte : bien plus dure.','Groupe de silicates magnésiens verts au toucher gras. Le chrysotile fibreux est de l''amiante : ne pas gratter ni respirer les poussières.','published'),
('Kaolinite','kaolinite','Al₂Si₂O₅(OH)₄','Silicates (phyllosilicates)','Triclinique',2,2.5,2.6,2.63,array['blanc','crème','jaunâtre']::text[],'blanc','terreux à nacré','opaque','parfait basal','terreuse','Masses argileuses compactes ou pulvérulentes, plaquettes microscopiques.',null,'Altération des feldspaths des granites et des pegmatites (kaolin). Le kaolin de Saint-Yrieix-la-Perche (Haute-Vienne) est à l''origine de la porcelaine de Limoges.','De Gaoling (Chine), colline d''où l''on tirait l''argile à porcelaine.',null,'Autres argiles : analyse nécessaire. Craie : effervescence.','Minéral argileux blanc, principal constituant du kaolin et matière première de la porcelaine.','published'),
('Chrysocolle','chrysocolle','(Cu,Al)₂H₂Si₂O₅(OH)₄·nH₂O','Silicates (phyllosilicates)','Orthorhombique',2.5,3.5,1.9,2.4,array['bleu vert','bleu ciel','vert']::text[],'bleu vert pâle','vitreux à terreux','translucide à opaque','aucun','conchoïdale','Encroûtements, masses botryoïdales, remplissages ; presque toujours mal cristallisée.',null,'Zones d''oxydation des gisements de cuivre.','Du grec chrysos, « or », et kolla, « colle » : un matériau semblable servait à souder l''or.','Chrysocolle silicifiée (pénétrée de calcédoine, bien plus dure).','Turquoise : plus dure. Malachite : effervescence, bandes.','Silicate de cuivre bleu turquoise, tendre, souvent mêlé de calcédoine ou de malachite.','published'),
('Pyrophyllite','pyrophyllite','Al₂Si₄O₁₀(OH)₂','Silicates (phyllosilicates)','Monoclinique',1,2,2.65,2.9,array['blanc','jaune','vert pâle','gris']::text[],'blanc','nacré à gras','translucide à opaque','parfait basal','irrégulière','Agrégats rayonnants de lamelles, masses compactes.',null,'Schistes et roches volcaniques altérées riches en aluminium, filons de quartz.','Du grec pyr, « feu », et phyllon, « feuille » : elle s''exfolie quand on la chauffe.',null,'Talc : quasi identique à l''œil, analyse nécessaire.','Silicate d''aluminium tendre et gras, jumeau d''aspect du talc, souvent en rosettes rayonnantes.','published'),
('Apophyllite','apophyllite','KCa₄Si₈O₂₀(F,OH)·8H₂O','Silicates (phyllosilicates)','Quadratique',4.5,5,2.3,2.4,array['incolore','blanc','vert','rosé']::text[],'blanc','vitreux, nacré sur la face basale','transparent à translucide','parfait basal','irrégulière','Pseudo-cubes, prismes à terminaison pyramidale, tablettes.',null,'Cavités des basaltes (Inde), avec stilbite et autres zéolites.','Du grec apo, « loin de », et phyllon, « feuille » : elle s''exfolie à la chaleur.','Nom de groupe : fluorapophyllite-(K) (la plus courante), hydroxyapophyllite-(K).','Quartz : plus dur, sans clivage. Calcite : effervescence.','Silicate aux cristaux limpides souvent pseudo-cubiques, vedette des géodes de basaltes indiens.','published'),
('Orthose','orthose','KAlSi₃O₈','Silicates (tectosilicates)','Monoclinique',6,6,2.55,2.63,array['blanc','rose','crème','gris']::text[],'blanc','vitreux','transparent à translucide','parfait et bon, deux directions à angle droit','conchoïdale à irrégulière','Prismes trapus, macles de Carlsbad, Baveno et Manebach.',null,'Granites, syénites, pegmatites, gneiss.','Du grec orthos, « droit », pour ses clivages à angle droit.','Adulaire (fentes alpines), pierre de lune (adularescence).','Quartz : pas de clivage. Microcline : clivages presque (mais pas tout à fait) à angle droit.','Feldspath potassique, référence de dureté 6, qui donne leur teinte rose à de nombreux granites.','published'),
('Microcline','microcline','KAlSi₃O₈','Silicates (tectosilicates)','Triclinique',6,6.5,2.54,2.57,array['blanc','rose','vert bleu (amazonite)']::text[],'blanc','vitreux','transparent à translucide','parfait, deux directions presque à angle droit','irrégulière','Grands prismes, macles, masses clivables ; macle quadrillée visible au microscope.',null,'Pegmatites, granites, gneiss.','Du grec mikros, « petit », et klinein, « incliner » : l''angle de ses clivages s''écarte légèrement de 90°.','Amazonite (vert bleuté, colorée par le plomb).','Orthose : clivages exactement à 90°. Albite : stries de macles polysynthétiques.','Feldspath potassique des pegmatites, dont la variété amazonite vert bleuté est très recherchée.','published'),
('Albite','albite','NaAlSi₃O₈','Silicates (tectosilicates)','Triclinique',6,6.5,2.6,2.65,array['blanc','incolore','gris','bleuté']::text[],'blanc','vitreux à nacré','transparent à translucide','parfait, deux directions presque à angle droit','irrégulière à conchoïdale','Tablettes, lamelles (cleavelandite), macles polysynthétiques visibles en fines stries.',null,'Pegmatites, granites, fentes alpines, roches métamorphiques de bas degré.','Du latin albus, « blanc ».','Cleavelandite (lamelles en rosettes), péristérite (irisée).','Orthose : pas de stries de macle. Quartz : pas de clivage.','Feldspath sodique blanc, pôle sodique de la série des plagioclases, souvent strié de fines macles.','published'),
('Labradorite','labradorite','(Ca,Na)(Al,Si)₄O₈','Silicates (tectosilicates)','Triclinique',6,6.5,2.68,2.72,array['gris sombre','reflets bleus, verts et dorés']::text[],'blanc','vitreux','translucide à opaque','parfait, deux directions presque à angle droit','irrégulière','Masses clivables ; cristaux rares.',null,'Gabbros, anorthosites, basaltes.','Du Labrador (Canada), où elle fut décrite.','Spectrolite (reflets très vifs, Finlande). Ce n''est pas une espèce IMA mais un terme de la série des plagioclases.','Sa labradorescence, visible sous un angle précis, est unique.','Plagioclase aux reflets bleus et verts changeants (labradorescence), dus à l''interférence de la lumière dans de fines lamelles.','published'),
('Anorthite','anorthite','CaAl₂Si₂O₈','Silicates (tectosilicates)','Triclinique',6,6.5,2.74,2.76,array['blanc','gris','incolore']::text[],'blanc','vitreux','transparent à translucide','parfait, deux directions presque à angle droit','conchoïdale à irrégulière','Prismes courts, grains ; macles polysynthétiques.',null,'Gabbros, basaltes, roches métamorphiques calciques, météorites et roches lunaires.','Du grec an-orthos, « non droit », pour ses clivages obliques.',null,'Albite : pôle sodique, plus léger.','Pôle calcique de la série des plagioclases, abondant dans les hautes terres de la Lune.','published'),
('Sanidine','sanidine','(K,Na)AlSi₃O₈','Silicates (tectosilicates)','Monoclinique',6,6,2.52,2.62,array['incolore','blanc','gris']::text[],'blanc','vitreux','transparent à translucide','parfait et bon, deux directions à angle droit','conchoïdale à irrégulière','Tablettes aplaties, macles de Carlsbad.',null,'Roches volcaniques (trachytes, rhyolites), refroidies rapidement.','Du grec sanis, « planche », pour ses cristaux tabulaires.',null,'Orthose : forme de plus basse température. Quartz : pas de clivage.','Feldspath potassique de haute température, limpide, typique des laves trachytiques.','published'),
('Leucite','leucite','KAlSi₂O₆','Silicates (tectosilicates)','Quadratique',5.5,6,2.45,2.5,array['blanc','gris','incolore']::text[],'blanc','vitreux','translucide','très médiocre','conchoïdale','Trapézoèdres (icositétraèdres) isolés dans la lave.',null,'Laves potassiques pauvres en silice (Vésuve, région de Rome).','Du grec leukos, « blanc ».',null,'Analcime : même forme, mais dans les cavités et non dans la masse de la roche.','Feldspathoïde en cristaux blancs à 24 faces, pseudo-cubiques, disséminés dans certaines laves.','published'),
('Néphéline','nepheline','(Na,K)AlSiO₄','Silicates (tectosilicates)','Hexagonal',5.5,6,2.55,2.66,array['blanc','gris','brun','rosé']::text[],'blanc','gras à vitreux','transparent à opaque','médiocre','subconchoïdale','Grains et masses ; prismes hexagonaux courts rares.',null,'Syénites néphéliniques, basaltes alcalins, phonolites.','Du grec nephelê, « nuage » : elle se trouble dans l''acide.',null,'Quartz : plus dur, sans éclat gras. Feldspaths : deux bons clivages.','Feldspathoïde à éclat gras, marqueur des roches pauvres en silice (où le quartz est absent).','published'),
('Sodalite','sodalite','Na₈(Al₆Si₆O₂₄)Cl₂','Silicates (tectosilicates)','Cubique',5.5,6,2.27,2.33,array['bleu roi','blanc','gris','violacé']::text[],'blanc à bleu très pâle','vitreux à gras','translucide à opaque','médiocre','conchoïdale à irrégulière','Masses veinées de blanc ; dodécaèdres rares.','Orange vif sous ultraviolets (hackmanite, qui change aussi de couleur à la lumière).','Syénites néphéliniques et roches alcalines.','Du sodium, qu''elle contient.','Hackmanite (ténébrescente : change de couleur à la lumière).','Lapis-lazuli (lazurite) : trait bleu, souvent piqueté de pyrite dorée.','Feldspathoïde bleu roi, souvent veiné de blanc, qui fluoresce en orange sous UV.','published'),
('Lazurite','lazurite','(Na,Ca)₈(Al₆Si₆O₂₄)(SO₄,S,Cl)₂','Silicates (tectosilicates)','Cubique',5,5.5,2.38,2.45,array['bleu intense','bleu violet']::text[],'bleu clair','vitreux à terne','translucide à opaque','médiocre','irrégulière','Masses granulaires ; dodécaèdres très rares.',null,'Marbres de métamorphisme de contact (Sar-e-Sang, Afghanistan, exploité depuis plus de 6 000 ans).','Du persan lazhward, « bleu ».','Constituant principal du lapis-lazuli (roche avec calcite, diopside et pyrite).','Sodalite : trait blanc, fluorescence orange. Lazulite : phosphate bien plus dur.','Feldspathoïde bleu intense, cœur du lapis-lazuli, dont on tirait autrefois le pigment outremer.','published'),
('Analcime','analcime','NaAlSi₂O₆·H₂O','Silicates (tectosilicates)','Cubique',5,5.5,2.24,2.29,array['incolore','blanc','rosé','gris']::text[],'blanc','vitreux','transparent à translucide','très médiocre','subconchoïdale','Trapézoèdres (icositétraèdres) limpides.',null,'Cavités de basaltes et de diabases, avec d''autres zéolites ; roches sédimentaires.','Du grec analkis, « sans force » : elle ne s''électrise que faiblement par frottement.',null,'Leucite : même forme, mais incluse dans la lave. Grenat : bien plus dur et dense.','Zéolite en cristaux limpides à 24 faces, fréquente dans les géodes des basaltes.','published'),
('Natrolite','natrolite','Na₂Al₂Si₃O₁₀·2H₂O','Silicates (tectosilicates)','Orthorhombique',5,5.5,2.2,2.26,array['incolore','blanc','jaunâtre']::text[],'blanc','vitreux à soyeux','transparent à translucide','parfait','irrégulière','Aiguilles et prismes fins en gerbes rayonnantes.','Parfois orangée ou jaune.','Cavités des basaltes et des phonolites, syénites néphéliniques.','Du grec nitron (natron, soude) et lithos, « pierre ».',null,'Scolécite et mésolite : aspect très proche (analyse ou flamme).','Zéolite sodique en aiguilles blanches rayonnantes dans les géodes de basaltes.','published'),
('Stilbite','stilbite','NaCa₄(Al₉Si₂₇O₇₂)·28H₂O','Silicates (tectosilicates)','Monoclinique',3.5,4,2.12,2.22,array['blanc','rose saumon','crème','orangé']::text[],'blanc','vitreux, nacré sur le clivage','transparent à translucide','parfait (une direction)','irrégulière','Gerbes caractéristiques en « nœud papillon », tablettes.',null,'Cavités des basaltes (Inde, Islande), avec apophyllite et heulandite.','Du grec stilbein, « briller ».','Nom de série : stilbite-Ca (la plus courante), stilbite-Na.','Heulandite : cristaux en cercueil, sans gerbes. Apophyllite : plus dure.','Zéolite en gerbes nacrées en forme de nœud papillon, très fréquente dans les basaltes.','published'),
('Heulandite','heulandite','(Ca,Na)₂₋₃Al₃(Al,Si)₂Si₁₃O₃₆·12H₂O','Silicates (tectosilicates)','Monoclinique',3,3.5,2.1,2.2,array['incolore','blanc','rose','rouge brique']::text[],'blanc','vitreux, nacré sur le clivage','transparent à translucide','parfait (une direction)','irrégulière','Cristaux tabulaires en forme de cercueil.',null,'Cavités des basaltes et des andésites, roches sédimentaires volcaniques.','Dédiée au collectionneur britannique Henry Heuland.','Nom de série : heulandite-Ca, heulandite-Na, heulandite-K…','Stilbite : gerbes. Calcite : effervescence.','Zéolite aux cristaux en forme de cercueil et à l''éclat nacré sur le clivage.','published'),
('Chabazite','chabazite','Ca₂Al₄Si₈O₂₄·12H₂O','Silicates (tectosilicates)','Trigonal',4,5,2.05,2.1,array['incolore','blanc','rose','jaunâtre']::text[],'blanc','vitreux','transparent à translucide','médiocre','irrégulière','Rhomboèdres presque cubiques, macles d''interpénétration (phacolite).',null,'Cavités des basaltes, avec d''autres zéolites.','Du grec chabazios, nom d''une pierre citée dans un poème antique.','Nom de série : chabazite-Ca (la plus courante), chabazite-Na, chabazite-K.','Calcite : effervescence, clivage parfait. Analcime : 24 faces.','Zéolite en rhomboèdres presque cubiques, fréquente dans les géodes de basaltes.','published'),
('Scolécite','scolecite','CaAl₂Si₃O₁₀·3H₂O','Silicates (tectosilicates)','Monoclinique',5,5.5,2.25,2.29,array['incolore','blanc']::text[],'blanc','vitreux à soyeux','transparent à translucide','parfait','irrégulière','Fines aiguilles en gerbes rayonnantes.',null,'Cavités des basaltes (Inde), avec apophyllite et stilbite.','Du grec skôlêx, « ver » : elle se tortille sous la flamme du chalumeau.',null,'Natrolite et mésolite : aspect très proche.','Zéolite calcique en aiguilles blanches rayonnantes, emblématique des géodes indiennes.','published'),
('Danburite','danburite','CaB₂Si₂O₈','Silicates (tectosilicates)','Orthorhombique',7,7.5,2.97,3.02,array['incolore','jaune pâle','rose pâle','brun']::text[],'blanc','vitreux à gras','transparent à translucide','très médiocre','subconchoïdale','Prismes à section losangique, terminés en biseau, rappelant la topaze.','Parfois bleu ciel.','Roches métamorphiques, filons hydrothermaux, dolomies.','De Danbury (Connecticut, États-Unis).',null,'Topaze : clivage basal parfait. Quartz : section hexagonale.','Borosilicate de calcium limpide, à la forme proche de celle de la topaze mais sans clivage net.','published')
insert into public.glossary_terms (term,slug,domain,definition,see_also,related_minerals) values
('Minéral','mineral','mineralogie','Substance naturelle, solide, de composition chimique définie (ou variable dans des limites précises) et à structure atomique ordonnée, formée par des processus géologiques.',array['Espèce minérale','Minéraloïde','Cristal']::text[],'{}'::text[]),
('Minéraloïde','mineraloide','mineralogie','Substance naturelle proche d''un minéral mais sans structure cristalline ordonnée (amorphe), ou de composition trop variable pour être une espèce.',array['Minéral','Amorphe']::text[],array['Opale']::text[]),
('Espèce minérale','espece-minerale','mineralogie','Minéral défini par une composition chimique et une structure cristalline propres, reconnu par l''Association minéralogique internationale (IMA). On en connaît un peu plus de 6 000.',array['IMA','Variété','Groupe minéral']::text[],'{}'::text[]),
('Variété','variete','mineralogie','Forme particulière d''une espèce minérale, distinguée par sa couleur, son aspect ou une impureté, sans changer de structure. L''améthyste est une variété de quartz.',array['Espèce minérale']::text[],array['Améthyste','Quartz','Béryl','Corindon']::text[]),
('Groupe minéral','groupe-mineral','mineralogie','Ensemble d''espèces partageant la même structure cristalline mais des compositions chimiques différentes, comme les grenats, les tourmalines ou les micas.',array['Série','Solution solide','Espèce minérale']::text[],array['Almandin','Schorl','Muscovite']::text[]),
('Série','serie','mineralogie','Ensemble continu de compositions entre deux ou plusieurs pôles purs qui se substituent l''un à l''autre, comme l''olivine entre forstérite et fayalite.',array['Solution solide','Groupe minéral']::text[],array['Olivine','Wolframite','Biotite']::text[]),
('Solution solide','solution-solide','mineralogie','Remplacement progressif d''un élément par un autre dans la structure d''un minéral, sans modification de celle-ci (par exemple le fer et le magnésium dans l''olivine).',array['Série','Isomorphisme']::text[],array['Olivine','Sphalérite']::text[]),
('Isomorphisme','isomorphisme','mineralogie','Propriété de minéraux de compositions différentes qui cristallisent avec la même structure, ce qui permet les solutions solides.',array['Solution solide','Polymorphisme']::text[],'{}'::text[]),
('Polymorphisme','polymorphisme','mineralogie','Existence d''une même composition chimique sous plusieurs structures cristallines différentes, appelées polymorphes. Le diamant et le graphite sont deux polymorphes du carbone.',array['Isomorphisme','Système cristallin']::text[],array['Diamant','Graphite','Calcite','Aragonite','Pyrite','Marcassite','Andalousite','Disthène','Sillimanite']::text[]),
('IMA','ima','mineralogie','Association minéralogique internationale (International Mineralogical Association). Sa commission valide les nouvelles espèces minérales et leurs noms.',array['Espèce minérale','Localité type']::text[],'{}'::text[]),
('Localité type','localite-type','mineralogie','Gisement où une espèce minérale a été décrite pour la première fois ; son échantillon de référence (holotype) y a été prélevé.',array['IMA','Gisement']::text[],array['Autunite']::text[]),
('Formule chimique','formule-chimique','mineralogie','Écriture qui indique les éléments constituant un minéral et leurs proportions, par exemple CaCO₃ pour la calcite.',array['Espèce minérale']::text[],array['Calcite']::text[]),
('Minerai','minerai','mineralogie','Roche ou minéral contenant un métal ou une substance utile en quantité suffisante pour être exploité avec profit.',array['Gangue','Gisement','Minéralisation']::text[],array['Galène','Chalcopyrite','Cassitérite']::text[]),
('Gangue','gangue','mineralogie','Minéraux sans valeur économique qui accompagnent le minerai dans un filon ; quartz, calcite, baryte ou fluorite en sont des exemples, souvent très recherchés des collectionneurs.',array['Minerai','Filon','Matrice']::text[],array['Quartz','Calcite','Baryte','Fluorite']::text[]),
('Paragenèse','paragenese','mineralogie','Association de minéraux formés ensemble dans les mêmes conditions ; elle renseigne sur l''histoire du gisement.',array['Association minérale','Gisement']::text[],'{}'::text[]),
('Association minérale','association-minerale','mineralogie','Ensemble de minéraux présents ensemble sur un même spécimen ou dans un même gisement, par exemple fluorite, quartz et galène.',array['Paragenèse']::text[],array['Fluorite','Galène','Quartz']::text[]),
('Minéral primaire','mineral-primaire','mineralogie','Minéral formé lors de la mise en place initiale d''un gisement ou d''une roche (par exemple les sulfures d''un filon).',array['Minéral secondaire']::text[],array['Galène','Chalcopyrite']::text[]),
('Minéral secondaire','mineral-secondaire','mineralogie','Minéral issu de la transformation d''un minéral primaire par altération, oxydation ou circulation d''eau, comme la malachite née de l''altération de la chalcopyrite.',array['Minéral primaire','Zone d''oxydation','Pseudomorphose']::text[],array['Malachite','Azurite','Pyromorphite','Cérusite']::text[]),
('Pseudomorphose','pseudomorphose','mineralogie','Remplacement d''un minéral par un autre qui en conserve la forme extérieure. On dit par exemple « malachite pseudomorphe d''azurite ».',array['Épigénie','Minéral secondaire']::text[],array['Malachite','Azurite','Goethite','Acanthite']::text[]),
('Épigénie','epigenie','mineralogie','Transformation chimique d''un minéral en un autre, molécule par molécule, en gardant sa forme ; terme proche de pseudomorphose.',array['Pseudomorphose']::text[],'{}'::text[]),
('Dureté','durete','mineralogie','Résistance d''un minéral à la rayure, mesurée sur l''échelle de Mohs : un minéral raye tous ceux de dureté inférieure.',array['Échelle de Mohs','Ténacité']::text[],'{}'::text[]),
('Échelle de Mohs','echelle-de-mohs','mineralogie','Échelle de dureté relative en dix degrés, définie par Friedrich Mohs en 1812 : 1 talc, 2 gypse, 3 calcite, 4 fluorite, 5 apatite, 6 orthose, 7 quartz, 8 topaze, 9 corindon, 10 diamant. Repères pratiques : ongle 2,5, pièce de cuivre 3,5, lame d''acier 5,5, verre 5,5 à 6.',array['Dureté']::text[],array['Talc','Gypse','Calcite','Fluorite','Apatite','Orthose','Quartz','Topaze','Corindon','Diamant']::text[]),
('Densité','densite','mineralogie','Rapport entre la masse d''un minéral et celle d''un même volume d''eau. La galène (7,5) paraît lourde en main, le gypse (2,3) léger.',array['Minéral']::text[],array['Galène','Baryte','Or']::text[]),
('Trait','trait','mineralogie','Couleur de la poudre d''un minéral, obtenue en le frottant sur une plaque de porcelaine non émaillée. Plus constant que la couleur, c''est un critère d''identification précieux : l''hématite, grise ou rouge, a toujours un trait rouge brun.',array['Couleur']::text[],array['Hématite','Pyrite','Sphalérite','Cinabre']::text[]),
('Couleur','couleur','mineralogie','Caractère le plus visible mais souvent trompeur : de nombreux minéraux prennent des couleurs variées selon leurs impuretés (minéraux allochromatiques), d''autres ont une couleur propre et constante (idiochromatiques).',array['Trait','Pléochroïsme']::text[],array['Fluorite','Quartz','Malachite','Azurite']::text[]),
('Éclat','eclat','mineralogie','Aspect de la surface d''un minéral sous la lumière : métallique, adamantin, vitreux, résineux, gras, nacré, soyeux ou terreux.',array['Éclat métallique','Éclat adamantin','Éclat vitreux','Éclat nacré','Éclat soyeux']::text[],'{}'::text[]),
('Éclat métallique','eclat-metallique','mineralogie','Éclat des métaux polis, propre aux minéraux opaques comme la galène, la pyrite ou l''or.',array['Éclat','Opaque']::text[],array['Galène','Pyrite','Or']::text[]),
('Éclat adamantin','eclat-adamantin','mineralogie','Éclat très vif et brillant, semblable à celui du diamant, typique des minéraux à fort indice de réfraction (cérusite, zircon, cinabre).',array['Éclat','Indice de réfraction']::text[],array['Diamant','Cérusite','Zircon','Anglésite']::text[]),
('Éclat vitreux','eclat-vitreux','mineralogie','Éclat du verre, le plus fréquent chez les minéraux transparents comme le quartz ou la fluorite.',array['Éclat']::text[],array['Quartz','Fluorite','Béryl']::text[]),
('Éclat nacré','eclat-nacre','mineralogie','Reflet irisé rappelant la nacre, visible sur les plans de clivage de minéraux en feuillets (muscovite, talc, apophyllite).',array['Éclat','Clivage']::text[],array['Muscovite','Talc','Apophyllite','Stilbite']::text[]),
('Éclat soyeux','eclat-soyeux','mineralogie','Reflet de fils de soie, propre aux minéraux fibreux (gypse fibreux, malachite, trémolite).',array['Éclat','Fibreux']::text[],array['Gypse','Malachite','Goethite']::text[]),
('Éclat résineux','eclat-resineux','mineralogie','Éclat rappelant celui de la résine ou du miel, fréquent chez la sphalérite, le soufre ou la pyromorphite.',array['Éclat']::text[],array['Sphalérite','Soufre','Pyromorphite']::text[]),
('Clivage','clivage','mineralogie','Tendance d''un minéral à se casser selon des plans plats et réguliers, liés aux faiblesses de sa structure. La calcite se clive en rhomboèdres, la galène en cubes, les micas en feuillets.',array['Cassure','Plan de séparation']::text[],array['Calcite','Galène','Muscovite','Fluorite']::text[]),
('Cassure','cassure','mineralogie','Aspect d''une surface de rupture qui ne suit pas un plan de clivage : conchoïdale, irrégulière, esquilleuse, crochue ou terreuse.',array['Cassure conchoïdale','Clivage']::text[],'{}'::text[]),
('Cassure conchoïdale','cassure-conchoidale','mineralogie','Cassure en surfaces courbes et lisses rappelant l''intérieur d''une coquille, typique du quartz, de l''opale et du verre.',array['Cassure']::text[],array['Quartz','Opale','Calcédoine']::text[]),
('Ténacité','tenacite','mineralogie','Comportement d''un minéral face à la déformation ou au choc : fragile, malléable, sectile, flexible ou élastique.',array['Malléable','Sectile','Élastique','Flexible']::text[],'{}'::text[]),
('Malléable','malleable','mineralogie','Se dit d''un minéral qui s''aplatit sous le marteau sans se briser, comme l''or, l''argent ou le cuivre natifs.',array['Ténacité']::text[],array['Or','Argent','Cuivre']::text[]),
('Sectile','sectile','mineralogie','Se dit d''un minéral qu''on peut couper en copeaux au couteau, comme l''acanthite ou la chalcocite.',array['Ténacité']::text[],array['Acanthite','Chalcocite']::text[]),
('Flexible','flexible','mineralogie','Se dit d''un minéral dont les lamelles se plient sans reprendre leur forme (talc, chlorite, gypse, orpiment).',array['Élastique','Ténacité']::text[],array['Talc','Clinochlore','Gypse','Orpiment']::text[]),
('Élastique','elastique','mineralogie','Se dit d''un minéral dont les lamelles pliées reprennent leur forme initiale, propriété caractéristique des micas.',array['Flexible','Ténacité']::text[],array['Muscovite','Biotite']::text[]),
('Transparent','transparent','mineralogie','Se dit d''un minéral à travers lequel on distingue nettement les objets ; translucide s''il laisse passer la lumière sans image nette, opaque s''il l''arrête.',array['Translucide','Opaque']::text[],array['Quartz','Calcite']::text[]),
('Translucide','translucide','mineralogie','Se dit d''un minéral qui laisse passer la lumière sans qu''on puisse voir nettement au travers.',array['Transparent','Opaque']::text[],array['Calcédoine']::text[]),
('Opaque','opaque','mineralogie','Se dit d''un minéral qui ne laisse pas passer la lumière, même en lame mince ; c''est le cas de la plupart des métaux et sulfures.',array['Transparent','Éclat métallique']::text[],array['Pyrite','Magnétite']::text[]),
('Fluorescence','fluorescence','mineralogie','Émission de lumière visible par un minéral éclairé par des ultraviolets ; elle cesse dès qu''on éteint la lampe. Le phénomène tire son nom de la fluorite.',array['Phosphorescence','Ultraviolets']::text[],array['Fluorite','Scheelite','Autunite','Adamite','Hydrozincite','Calcite']::text[]),
('Phosphorescence','phosphorescence','mineralogie','Émission de lumière qui persiste quelques instants après l''arrêt de l''éclairage ultraviolet.',array['Fluorescence']::text[],array['Calcite','Spodumène']::text[]),
('Ultraviolets','ultraviolets','mineralogie','Rayonnement invisible utilisé pour révéler la fluorescence. Les lampes à UV courts (254 nm) et longs (365 nm) donnent des réponses différentes ; les UV courts sont dangereux pour les yeux et la peau.',array['Fluorescence']::text[],array['Scheelite','Hydrozincite']::text[]),
('Triboluminescence','triboluminescence','mineralogie','Émission de lumière provoquée par le frottement, le grattage ou l''écrasement d''un minéral, observée chez certaines sphalérites.',array['Fluorescence']::text[],array['Sphalérite']::text[]),
('Pléochroïsme','pleochroisme','mineralogie','Changement de couleur d''un cristal selon la direction d''observation, très marqué chez la cordiérite, la tourmaline ou l''épidote.',array['Anisotrope','Couleur']::text[],array['Cordiérite','Épidote','Elbaïte']::text[]),
('Biréfringence','birefringence','mineralogie','Dédoublement d''un rayon lumineux en deux rayons en traversant un cristal anisotrope. Spectaculaire dans le spath d''Islande (calcite limpide), qui fait voir double.',array['Anisotrope','Indice de réfraction']::text[],array['Calcite']::text[]),
('Dispersion','dispersion','mineralogie','Décomposition de la lumière blanche en couleurs par un cristal, à l''origine des « feux » du diamant, de la titanite ou du démantoïde.',array['Indice de réfraction']::text[],array['Diamant','Titanite','Andradite']::text[]),
('Chatoyance','chatoyance','mineralogie','Bande lumineuse mobile, dite « œil-de-chat », due à de fines inclusions fibreuses parallèles ; visible sur un cabochon.',array['Astérisme','Inclusion']::text[],array['Chrysobéryl','Quartz']::text[]),
('Astérisme','asterisme','mineralogie','Étoile lumineuse à quatre ou six branches visible sur certaines gemmes taillées en cabochon (saphir ou rubis étoilé), due à des inclusions aiguillées orientées.',array['Chatoyance','Inclusion']::text[],array['Corindon']::text[]),
('Labradorescence','labradorescence','mineralogie','Reflets colorés changeants (bleu, vert, doré) visibles sous un certain angle, dus à l''interférence de la lumière dans de fines lamelles, typiques de la labradorite.',array['Irisation','Adularescence']::text[],array['Labradorite']::text[]),
('Adularescence','adularescence','mineralogie','Reflet laiteux et bleuté flottant à la surface de la pierre de lune (feldspath), dû à la diffusion de la lumière.',array['Labradorescence']::text[],array['Orthose']::text[]),
('Irisation','irisation','mineralogie','Reflets aux couleurs de l''arc-en-ciel à la surface ou à l''intérieur d''un minéral, dus à une fine pellicule d''altération ou à des fissures.',array['Labradorescence']::text[],array['Bornite','Chalcopyrite','Hématite','Goethite']::text[]),
('Jeux de couleurs','jeux-de-couleurs','mineralogie','Éclairs de couleurs pures qui changent avec l''angle de vue dans l''opale noble, produits par un empilement régulier de sphères de silice.',array['Irisation']::text[],array['Opale']::text[]),
('Magnétisme','magnetisme','mineralogie','Propriété d''être attiré par un aimant, forte chez la magnétite, plus faible chez la pyrrhotite, l''ilménite ou la chromite.',array['Densité']::text[],array['Magnétite','Pyrrhotite','Ilménite','Chromite']::text[]),
('Radioactivité','radioactivite','mineralogie','Émission naturelle de rayonnements par des minéraux contenant de l''uranium ou du thorium. Ces spécimens se conservent dans une boîte fermée, à l''écart des lieux de vie, et se manipulent le moins possible.',array['Métamicte']::text[],array['Uraninite','Autunite','Torbernite','Monazite']::text[]),
('Métamicte','metamicte','mineralogie','Se dit d''un minéral dont la structure cristalline a été détruite par sa propre radioactivité au fil du temps, tout en gardant sa forme extérieure.',array['Radioactivité']::text[],array['Zircon']::text[]),
('Piézoélectricité','piezoelectricite','mineralogie','Apparition de charges électriques quand un cristal est comprimé ; utilisée dans les montres à quartz et les briquets.',array['Pyroélectricité']::text[],array['Quartz','Schorl']::text[]),
('Pyroélectricité','pyroelectricite','mineralogie','Apparition de charges électriques quand un cristal est chauffé ; une tourmaline chauffée attire alors les poussières.',array['Piézoélectricité','Hémimorphisme']::text[],array['Schorl','Elbaïte','Hémimorphite']::text[]),
('Effervescence','effervescence','mineralogie','Dégagement de bulles de gaz carbonique quand on dépose une goutte d''acide dilué sur un carbonate ; test simple pour reconnaître la calcite.',array['Carbonate']::text[],array['Calcite','Malachite','Azurite','Cérusite','Dolomite']::text[]),
('Carbonate','carbonate','mineralogie','Minéral contenant le groupe CO₃, comme la calcite, la dolomite ou la malachite ; la plupart font effervescence à l''acide.',array['Effervescence']::text[],array['Calcite','Dolomite','Malachite','Sidérite']::text[]),
('Sulfure','sulfure','mineralogie','Minéral associant un métal au soufre, comme la pyrite, la galène ou la sphalérite ; les sulfures sont les principaux minerais métalliques.',array['Sulfosel','Minerai']::text[],array['Pyrite','Galène','Sphalérite','Chalcopyrite']::text[]),
('Sulfosel','sulfosel','mineralogie','Minéral associant un métal, du soufre et un semi-métal (antimoine, arsenic, bismuth), comme la tétraédrite ou la bournonite.',array['Sulfure']::text[],array['Tétraédrite','Bournonite','Proustite','Boulangérite']::text[]),
('Silicate','silicate','mineralogie','Minéral construit autour du groupe SiO₄ ; c''est la classe la plus abondante de l''écorce terrestre. On les classe selon l''assemblage des tétraèdres : nésosilicates, sorosilicates, cyclosilicates, inosilicates, phyllosilicates et tectosilicates.',array['Tétraèdre','Feldspath','Zéolite']::text[],array['Orthose','Olivine','Muscovite','Béryl']::text[]),
('Feldspath','feldspath','mineralogie','Famille de silicates d''aluminium la plus abondante de la croûte terrestre : feldspaths potassiques (orthose, microcline, sanidine) et plagioclases (de l''albite à l''anorthite).',array['Plagioclase','Silicate']::text[],array['Orthose','Microcline','Albite','Labradorite','Sanidine']::text[]),
('Plagioclase','plagioclase','mineralogie','Série de feldspaths entre l''albite (sodique) et l''anorthite (calcique), souvent striés de fines macles polysynthétiques.',array['Feldspath','Macle polysynthétique']::text[],array['Albite','Labradorite','Anorthite']::text[]),
('Zéolite','zeolite','mineralogie','Famille de silicates à charpente poreuse contenant de l''eau, fréquents dans les géodes des basaltes (stilbite, natrolite, chabazite…).',array['Géode','Basalte']::text[],array['Stilbite','Natrolite','Chabazite','Heulandite','Analcime','Scolécite']::text[]),
('Mica','mica','mineralogie','Famille de silicates en feuillets élastiques qui se détachent à l''ongle : muscovite, biotite, phlogopite, lépidolite.',array['Élastique','Clivage']::text[],array['Muscovite','Biotite','Phlogopite','Lépidolite']::text[]),
('Grenat','grenat','mineralogie','Groupe de silicates cubiques aux cristaux à 12 ou 24 faces : almandin, pyrope, spessartine, grossulaire, andradite, uvarovite.',array['Rhombododécaèdre','Icositétraèdre']::text[],array['Almandin','Pyrope','Spessartine','Grossulaire','Andradite','Uvarovite']::text[]),
('Tourmaline','tourmaline','mineralogie','Groupe de borosilicates en prismes striés à section triangulaire, aux couleurs très variées : schorl (noir), elbaïte (gemme), dravite (brune).',array['Pyroélectricité']::text[],array['Schorl','Elbaïte','Dravite']::text[]),
('Pyroxène','pyroxene','mineralogie','Famille de silicates en chaînes simples (augite, diopside, jadéite…), aux deux clivages presque perpendiculaires (environ 87°).',array['Amphibole','Silicate']::text[],array['Augite','Diopside','Jadéite','Spodumène','Aegyrine']::text[]),
('Amphibole','amphibole','mineralogie','Famille de silicates en chaînes doubles (hornblende, actinote, trémolite…), aux deux clivages formant des angles de 56° et 124°.',array['Pyroxène','Amiante']::text[],array['Hornblende','Actinote','Trémolite','Glaucophane']::text[]),
('Amiante','amiante','mineralogie','Terme commercial désignant des minéraux naturellement fibreux (chrysotile, certaines amphiboles) dont les fibres inhalées sont cancérigènes. Ne jamais gratter, scier ni réduire en poudre ces spécimens.',array['Fibreux','Amphibole']::text[],array['Serpentine','Trémolite','Actinote']::text[]),
('Gemme','gemme','mineralogie','Minéral (ou matière organique) apprécié pour sa beauté, sa rareté et sa durabilité, taillé en bijouterie : diamant, rubis, saphir, émeraude, mais aussi grenat, topaze, tourmaline…',array['Cabochon','Traitement']::text[],array['Diamant','Corindon','Béryl','Topaze']::text[]),
('Cabochon','cabochon','mineralogie','Taille en forme de dôme poli, sans facettes, utilisée pour les pierres opaques ou à effets (œil-de-chat, astérisme, opale).',array['Gemme','Chatoyance']::text[],array['Turquoise','Opale']::text[]),
('Traitement','traitement','mineralogie','Modification artificielle d''un minéral pour en améliorer l''aspect : chauffage, irradiation, teinture, huilage, stabilisation à la résine. Un vendeur honnête le signale.',array['Synthétique','Gemme']::text[],array['Topaze','Zoïsite','Turquoise','Améthyste']::text[]),
('Synthétique','synthetique','mineralogie','Cristal fabriqué en laboratoire, de même composition et structure que son équivalent naturel (quartz, corindon, bismuth…), à distinguer d''une imitation (verre, plastique).',array['Traitement']::text[],array['Bismuth','Chalcanthite','Corindon']::text[]),
('Spécimen','specimen','mineralogie','Échantillon minéral de collection, choisi pour la qualité de ses cristaux, son esthétique ou sa rareté, idéalement accompagné de sa provenance précise.',array['Matrice','Formats de collection','Étiquette']::text[],'{}'::text[]),
('Matrice','matrice','mineralogie','Roche ou minéral sur lequel reposent les cristaux d''un spécimen. Un cristal « sur matrice » est souvent plus recherché qu''un cristal isolé.',array['Spécimen','Flottant','Gangue']::text[],'{}'::text[]),
('Flottant','flottant','mineralogie','Cristal ou groupe de cristaux qui s''est formé sans point d''attache (en suspension dans une argile, par exemple), et qui est donc terminé sur toutes ses faces.',array['Matrice','Biterminé']::text[],array['Quartz','Gypse']::text[]),
('Biterminé','bitermine','mineralogie','Se dit d''un cristal terminé à ses deux extrémités, signe d''une croissance libre ou d''un détachement ancien de sa base.',array['Flottant']::text[],array['Quartz']::text[]),
('Formats de collection','formats-de-collection','mineralogie','Classement usuel des spécimens par taille : micromonté (à observer à la loupe binoculaire, quelques millimètres), thumbnail (jusqu''à environ 2,5 cm), miniature (environ 2,5 à 5 cm), petit cabinet (environ 5 à 7,5 cm), cabinet (au-delà).',array['Micromonté','Spécimen']::text[],'{}'::text[]),
('Micromonté','micromonte','mineralogie','Petit spécimen dont les cristaux, souvent millimétriques, s''observent à la loupe binoculaire ; ils sont traditionnellement fixés dans une petite boîte.',array['Formats de collection']::text[],'{}'::text[]),
('Étiquette','etiquette','mineralogie','Fiche accompagnant un spécimen : nom du minéral, gisement, commune, département, pays, date de récolte, récolteur, ancienne collection. Une provenance précise augmente beaucoup la valeur d''un spécimen.',array['Spécimen','Localité type']::text[],'{}'::text[]),
('Inclusion','inclusion','mineralogie','Matière (minéral, liquide, gaz) piégée à l''intérieur d''un cristal pendant sa croissance, comme les aiguilles de rutile dans le quartz.',array['Fantôme','Chatoyance']::text[],array['Quartz','Rutile']::text[]),
('Fantôme','fantome','mineralogie','Silhouette d''un stade de croissance ancien visible à l''intérieur d''un cristal transparent, soulignée par une fine pellicule d''un autre minéral.',array['Inclusion','Zonage']::text[],array['Quartz','Fluorite','Calcite']::text[]),
('Zonage','zonage','mineralogie','Répartition de couleurs en bandes ou en zones successives dans un cristal, traduisant des changements de composition pendant sa croissance.',array['Fantôme']::text[],array['Fluorite','Elbaïte','Améthyste']::text[]),
('Géode','geode','mineralogie','Cavité plus ou moins sphérique d''une roche dont la paroi est tapissée de cristaux tournés vers le centre (quartz, calcite, célestine…).',array['Druse','Nodule']::text[],array['Améthyste','Calcédoine','Célestine','Calcite']::text[]),
('Druse','druse','mineralogie','Surface de roche couverte de nombreux petits cristaux serrés et orientés vers l''extérieur.',array['Géode']::text[],array['Quartz','Uvarovite']::text[]),
('Nodule','nodule','mineralogie','Masse arrondie d''un minéral ou d''une roche, plus dure que son encaissant, formée par concentration autour d''un noyau (silex, marcassite…).',array['Concrétion','Géode']::text[],array['Marcassite','Calcédoine']::text[]),
('Concrétion','concretion','mineralogie','Dépôt formé par accumulation de couches successives de matière minérale, comme les stalactites ou les mamelons de malachite.',array['Stalactite','Botryoïdal']::text[],array['Malachite','Calcite','Goethite']::text[]),
('Stalactite','stalactite','mineralogie','Concrétion qui pend d''un plafond, formée goutte à goutte ; la stalagmite s''élève du sol à sa rencontre.',array['Concrétion','Karst']::text[],array['Calcite','Aragonite','Rhodochrosite','Goethite']::text[]),
('Botryoïdal','botryoidal','mineralogie','En grappe de raisin : agrégat de petites sphères accolées (hématite, malachite, prehnite). On dit aussi mamelonné.',array['Réniforme','Concrétion']::text[],array['Hématite','Malachite','Prehnite','Smithsonite']::text[]),
('Réniforme','reniforme','mineralogie','En forme de rein : surface arrondie et bosselée, à grandes courbures (hématite « rognon »).',array['Botryoïdal']::text[],array['Hématite']::text[]),
('Fibreux','fibreux','mineralogie','Formé de fibres fines et parallèles ou rayonnantes (gypse fibreux, malachite, amiante).',array['Fibro-radié','Éclat soyeux','Amiante']::text[],array['Gypse','Goethite','Serpentine']::text[]),
('Fibro-radié','fibro-radie','mineralogie','Formé de fibres ou d''aiguilles qui rayonnent à partir d''un centre, visible en coupe dans la wavellite, la goethite ou la malachite.',array['Fibreux']::text[],array['Wavellite','Goethite','Malachite']::text[]),
('Aciculaire','aciculaire','mineralogie','En aiguilles fines et allongées (natrolite, millérite, stibine).',array['Capillaire','Prismatique']::text[],array['Natrolite','Millérite','Stibine','Scolécite']::text[]),
('Capillaire','capillaire','mineralogie','En filaments aussi fins que des cheveux (millérite, chalcotrichite).',array['Aciculaire']::text[],array['Millérite','Cuprite']::text[]),
('Prismatique','prismatique','mineralogie','Allongé selon une direction, en forme de prisme (tourmaline, béryl, quartz).',array['Tabulaire','Prisme']::text[],array['Schorl','Béryl','Quartz']::text[]),
('Tabulaire','tabulaire','mineralogie','Aplati en tablette (baryte, wulfénite, hématite).',array['Prismatique','Lamellaire']::text[],array['Baryte','Wulfénite','Hématite']::text[]),
('Lamellaire','lamellaire','mineralogie','En lamelles minces empilées ou juxtaposées (micas, baryte, cleavelandite).',array['Tabulaire']::text[],array['Muscovite','Baryte','Albite']::text[]),
('Dendrite','dendrite','mineralogie','Dessin ramifié en forme de fougère sur les plans de fracture d''une roche, formé le plus souvent d''oxydes de manganèse ; ce n''est pas un fossile végétal. Les métaux natifs forment aussi des cristaux dendritiques.','{}'::text[],array['Pyrolusite','Cuivre','Argent','Or']::text[]),
('Encroûtement','encroutement','mineralogie','Mince couche minérale qui recouvre la surface d''une roche ou d''autres cristaux.',array['Concrétion']::text[],array['Hydrozincite','Chrysocolle']::text[]),
('Rose des sables','rose-des-sables','mineralogie','Agrégat de cristaux lenticulaires de gypse ou de baryte, englobant des grains de sable, disposés en pétales ; formé dans les sables des déserts.',array['Évaporite']::text[],array['Gypse','Baryte']::text[]),
('Ternissure','ternissure','mineralogie','Altération superficielle qui modifie la couleur d''un minéral (argent noirci, bornite irisée) ; une cassure fraîche révèle la vraie couleur.',array['Irisation']::text[],array['Argent','Bornite','Stibine']::text[]),
('Maladie de la pyrite','maladie-de-la-pyrite','mineralogie','Décomposition de certaines pyrites et marcassites à l''humidité, qui se couvrent de sulfates blancs et produisent de l''acide. On la prévient en conservant les spécimens au sec.',array['Sulfure']::text[],array['Pyrite','Marcassite']::text[]),
('Nettoyage','nettoyage','mineralogie','Préparation d''un spécimen pour en révéler les cristaux : eau, brosse douce, ultrasons, voire acides dilués selon le minéral (l''acide oxalique enlève les taches de fer du quartz). Chaque minéral a ses sensibilités : un test préalable sur une zone discrète est prudent.',array['Spécimen']::text[],array['Quartz']::text[]),
('Cristal','cristal','cristallographie','Solide dont les atomes sont disposés selon un motif qui se répète régulièrement dans les trois directions de l''espace ; lorsqu''il croît librement, il développe des faces planes.',array['Réseau cristallin','Maille','Face']::text[],array['Quartz']::text[]),
('Réseau cristallin','reseau-cristallin','cristallographie','Arrangement ordonné et périodique des atomes d''un cristal, obtenu en répétant une maille élémentaire dans l''espace.',array['Maille','Cristal']::text[],'{}'::text[]),
('Maille','maille','cristallographie','Plus petit volume du réseau cristallin qui, répété dans les trois directions, reconstitue tout le cristal. Sa forme définit le système cristallin.',array['Réseau cristallin','Système cristallin']::text[],'{}'::text[]),
('Système cristallin','systeme-cristallin','cristallographie','Classement des cristaux selon la symétrie de leur maille. On en distingue sept : cubique, quadratique, hexagonal, trigonal, orthorhombique, monoclinique et triclinique.',array['Cubique','Quadratique','Hexagonal','Trigonal','Orthorhombique','Monoclinique','Triclinique']::text[],'{}'::text[]),
('Cubique','cubique','cristallographie','Système cristallin le plus symétrique : trois axes de même longueur à angle droit. Formes typiques : cube, octaèdre, dodécaèdre. On dit aussi isométrique.',array['Système cristallin','Cube','Octaèdre']::text[],array['Fluorite','Pyrite','Galène','Halite','Almandin','Diamant']::text[]),
('Quadratique','quadratique','cristallographie','Système cristallin à trois axes perpendiculaires, dont deux de même longueur ; les prismes ont une section carrée. On dit aussi tétragonal.',array['Système cristallin']::text[],array['Zircon','Cassitérite','Wulfénite','Vésuvianite','Rutile']::text[]),
('Hexagonal','hexagonal','cristallographie','Système cristallin caractérisé par un axe de symétrie d''ordre 6 : prismes à section hexagonale.',array['Système cristallin','Trigonal']::text[],array['Béryl','Apatite','Vanadinite','Pyromorphite']::text[]),
('Trigonal','trigonal','cristallographie','Système cristallin caractérisé par un axe de symétrie d''ordre 3 ; formes typiques : rhomboèdre, scalénoèdre, prisme à section triangulaire. On le rattache parfois au système hexagonal.',array['Système cristallin','Rhomboèdre','Scalénoèdre']::text[],array['Quartz','Calcite','Corindon','Schorl','Hématite']::text[]),
('Orthorhombique','orthorhombique','cristallographie','Système cristallin à trois axes perpendiculaires de longueurs différentes.',array['Système cristallin']::text[],array['Baryte','Topaze','Aragonite','Soufre','Stibine']::text[]),
('Monoclinique','monoclinique','cristallographie','Système cristallin à trois axes de longueurs différentes, dont un seul angle n''est pas droit.',array['Système cristallin']::text[],array['Gypse','Orthose','Azurite','Malachite','Épidote']::text[]),
('Triclinique','triclinique','cristallographie','Système cristallin le moins symétrique : trois axes de longueurs différentes, aucun à angle droit.',array['Système cristallin']::text[],array['Microcline','Albite','Disthène','Axinite','Turquoise']::text[]),
('Amorphe','amorphe','cristallographie','Se dit d''une matière sans arrangement atomique ordonné, donc sans faces cristallines ni clivage : verre, opale.',array['Minéraloïde','Cristal']::text[],array['Opale']::text[]),
('Symétrie','symetrie','cristallographie','Propriété d''un cristal de se superposer à lui-même par une opération : rotation autour d''un axe, réflexion dans un plan ou inversion par un centre.',array['Axe de symétrie','Plan de symétrie','Centre de symétrie','Classe cristalline']::text[],'{}'::text[]),
('Axe de symétrie','axe-de-symetrie','cristallographie','Droite autour de laquelle une rotation d''une fraction de tour (1/2, 1/3, 1/4 ou 1/6) ramène le cristal dans une position identique.',array['Symétrie']::text[],'{}'::text[]),
('Plan de symétrie','plan-de-symetrie','cristallographie','Plan qui partage un cristal en deux moitiés images l''une de l''autre dans un miroir.',array['Symétrie']::text[],'{}'::text[]),
('Centre de symétrie','centre-de-symetrie','cristallographie','Point au centre du cristal tel que chaque face a une face identique et parallèle à l''opposé.',array['Symétrie']::text[],'{}'::text[]),
('Classe cristalline','classe-cristalline','cristallographie','Groupe de symétrie d''un cristal. Il en existe 32, réparties entre les sept systèmes cristallins.',array['Système cristallin','Groupe d''espace']::text[],'{}'::text[]),
('Groupe d''espace','groupe-d-espace','cristallographie','Description complète de la symétrie de l''arrangement atomique d''un cristal ; il en existe 230.',array['Classe cristalline']::text[],'{}'::text[]),
('Face','face','cristallographie','Surface plane naturelle qui limite un cristal ; son orientation reflète la structure interne.',array['Arête','Forme cristalline']::text[],'{}'::text[]),
('Arête','arete','cristallographie','Ligne d''intersection de deux faces d''un cristal. Des arêtes vives et intactes sont un critère de qualité d''un spécimen.',array['Face']::text[],'{}'::text[]),
('Loi de Sténon','loi-de-stenon','cristallographie','Loi de la constance des angles, énoncée par Nicolas Sténon en 1669 : les angles entre faces correspondantes sont les mêmes pour tous les cristaux d''une même espèce, quelle que soit leur taille.',array['Goniomètre','Face']::text[],array['Quartz']::text[]),
('Goniomètre','goniometre','cristallographie','Instrument de mesure des angles entre les faces d''un cristal, outil fondateur de la cristallographie.',array['Loi de Sténon']::text[],'{}'::text[]),
('Indices de Miller','indices-de-miller','cristallographie','Trois nombres entiers entre parenthèses, comme (111) ou (100), qui désignent l''orientation d''une face ou d''un plan par rapport aux axes du cristal.',array['Face']::text[],'{}'::text[]),
('Forme cristalline','forme-cristalline','cristallographie','Ensemble de faces équivalentes par symétrie (cube, octaèdre, prisme…). Un cristal réel combine souvent plusieurs formes.',array['Habitus','Faciès']::text[],'{}'::text[]),
('Habitus','habitus','cristallographie','Aspect général d''un cristal ou d''un agrégat : prismatique, tabulaire, aciculaire, massif, botryoïdal… Il dépend des conditions de croissance.',array['Faciès','Forme cristalline']::text[],'{}'::text[]),
('Faciès','facies','cristallographie','Combinaison de formes cristallines caractéristique d''un gisement : la calcite, par exemple, présente des faciès très différents selon les localités.',array['Habitus']::text[],array['Calcite']::text[]),
('Cube','cube','cristallographie','Forme du système cubique à six faces carrées identiques.',array['Cubique','Octaèdre']::text[],array['Fluorite','Pyrite','Galène','Halite']::text[]),
('Octaèdre','octaedre','cristallographie','Forme à huit faces triangulaires équilatérales, comme deux pyramides à base carrée accolées.',array['Cubique','Cube']::text[],array['Fluorite','Magnétite','Spinelle','Diamant']::text[]),
('Rhombododécaèdre','rhombododecaedre','cristallographie','Forme du système cubique à douze faces en losange, typique des grenats.',array['Grenat','Cubique']::text[],array['Almandin','Grossulaire','Andradite']::text[]),
('Icositétraèdre','icositetraedre','cristallographie','Forme du système cubique à 24 faces trapézoïdales (trapézoèdre), fréquente chez les grenats, la leucite et l''analcime.',array['Grenat']::text[],array['Almandin','Leucite','Analcime','Spessartine']::text[]),
('Pyritoèdre','pyritoedre','cristallographie','Dodécaèdre à douze faces pentagonales, forme caractéristique de la pyrite.',array['Cubique']::text[],array['Pyrite']::text[]),
('Tétraèdre','tetraedre','cristallographie','Forme à quatre faces triangulaires, typique de la tétraédrite et de la sphalérite. Désigne aussi le groupe SiO₄ à la base des silicates.',array['Cubique','Silicate']::text[],array['Tétraédrite','Sphalérite']::text[]),
('Rhomboèdre','rhomboedre','cristallographie','Forme à six faces en losange, comme un cube « écrasé » selon une diagonale ; c''est aussi la forme du clivage de la calcite.',array['Trigonal','Clivage']::text[],array['Calcite','Dolomite','Sidérite','Rhodochrosite']::text[]),
('Scalénoèdre','scalenoedre','cristallographie','Forme à faces triangulaires inégales, en double pyramide pointue ; la calcite « dent de cochon » en est l''exemple classique.',array['Trigonal']::text[],array['Calcite']::text[]),
('Prisme','prisme','cristallographie','Forme ouverte dont les faces sont parallèles à un même axe, comme les faces latérales d''un cristal de quartz ou de béryl.',array['Prismatique','Pinacoïde']::text[],array['Quartz','Béryl','Schorl']::text[]),
('Pinacoïde','pinacoide','cristallographie','Forme ouverte constituée de deux faces parallèles, comme la face plane qui termine un prisme de béryl.',array['Prisme']::text[],array['Béryl']::text[]),
('Bipyramide','bipyramide','cristallographie','Forme composée de deux pyramides accolées par leur base.',array['Octaèdre']::text[],array['Anatase','Soufre','Scheelite']::text[]),
('Hémimorphisme','hemimorphisme','cristallographie','Propriété d''un cristal dont les deux extrémités ont des formes différentes, faute de symétrie entre elles.',array['Pyroélectricité']::text[],array['Hémimorphite','Schorl']::text[]),
('Énantiomorphe','enantiomorphe','cristallographie','Se dit de deux cristaux images l''un de l''autre dans un miroir, non superposables, comme le quartz droit et le quartz gauche.',array['Symétrie']::text[],array['Quartz']::text[]),
('Macle','macle','cristallographie','Association de deux ou plusieurs cristaux d''une même espèce, orientés les uns par rapport aux autres selon une loi précise.',array['Macle de contact','Macle d''interpénétration','Macle polysynthétique']::text[],array['Staurotide','Orthose','Gypse','Fluorite']::text[]),
('Macle de contact','macle-de-contact','cristallographie','Macle dont les individus sont accolés le long d''un plan commun, comme la macle du Japon du quartz ou les « fers de lance » du gypse.',array['Macle','Macle du Japon','Macle en fer de lance']::text[],array['Gypse','Quartz','Spinelle']::text[]),
('Macle d''interpénétration','macle-d-interpenetration','cristallographie','Macle dont les individus se traversent mutuellement, comme les cubes interpénétrés de fluorite ou les croix de staurotide.',array['Macle']::text[],array['Fluorite','Staurotide','Pyrite','Chabazite']::text[]),
('Macle polysynthétique','macle-polysynthetique','cristallographie','Répétition de nombreuses lamelles maclées parallèles, visible sous forme de fines stries, typique des plagioclases.',array['Macle','Plagioclase']::text[],array['Albite','Labradorite']::text[]),
('Macle en genou','macle-en-genou','cristallographie','Macle de deux prismes formant un angle, comme un genou plié, typique du rutile et de la cassitérite.',array['Macle']::text[],array['Rutile','Cassitérite']::text[]),
('Macle du Japon','macle-du-japon','cristallographie','Macle du quartz où deux cristaux aplatis se rejoignent en formant un angle d''environ 84°, en forme de cœur ou de V.',array['Macle de contact']::text[],array['Quartz']::text[]),
('Macle en fer de lance','macle-en-fer-de-lance','cristallographie','Macle du gypse (et de la marcassite) en forme de pointe de lance ou de queue d''aronde.',array['Macle de contact']::text[],array['Gypse','Marcassite']::text[]),
('Macle de Carlsbad','macle-de-carlsbad','cristallographie','Macle fréquente de l''orthose et de la sanidine, où deux cristaux s''interpénètrent côte à côte.',array['Macle','Feldspath']::text[],array['Orthose','Sanidine']::text[]),
('Macle du spinelle','macle-du-spinelle','cristallographie','Macle de deux octaèdres selon une face commune, formant un cristal aplati triangulaire ; fréquente chez le spinelle, la magnétite et le diamant.',array['Macle','Octaèdre']::text[],array['Spinelle','Magnétite','Diamant']::text[]),
('Stries','stries','cristallographie','Fines lignes parallèles sur les faces d''un cristal, dues à l''alternance de deux formes ou à des macles ; horizontales sur les prismes de quartz, en longueur sur la tourmaline.',array['Macle polysynthétique']::text[],array['Quartz','Pyrite','Schorl','Stibine']::text[]),
('Croissance en trémie','croissance-en-tremie','cristallographie','Croissance plus rapide des arêtes que du centre des faces, donnant des cristaux creusés en escalier (halite, bismuth de laboratoire).',array['Cristal']::text[],array['Halite','Bismuth']::text[]),
('Sceptre','sceptre','cristallographie','Cristal dont l''extrémité s''est élargie lors d''une seconde phase de croissance, comme une tête posée sur une tige.',array['Fantôme']::text[],array['Quartz','Améthyste']::text[]),
('Épitaxie','epitaxie','cristallographie','Croissance orientée d''un minéral sur un autre, dont la structure guide son alignement (rutile sur hématite, par exemple).',array['Cristal']::text[],array['Rutile','Hématite']::text[]),
('Polytype','polytype','cristallographie','Variante d''une même structure obtenue en empilant différemment des couches identiques ; fréquent chez les micas, la molybdénite ou la pyrrhotite.',array['Polymorphisme']::text[],array['Molybdénite','Pyrrhotite']::text[]),
('Isotrope','isotrope','cristallographie','Se dit d''un milieu dont les propriétés optiques sont les mêmes dans toutes les directions : cristaux cubiques et matières amorphes. Les autres sont anisotropes.',array['Anisotrope']::text[],array['Fluorite','Opale']::text[]),
('Anisotrope','anisotrope','cristallographie','Se dit d''un cristal dont les propriétés (optiques, dureté…) varient selon la direction, comme la dureté du disthène.',array['Isotrope','Biréfringence','Pléochroïsme']::text[],array['Disthène','Calcite']::text[]),
('Indice de réfraction','indice-de-refraction','cristallographie','Mesure de la déviation de la lumière lorsqu''elle pénètre dans un minéral ; plus il est élevé, plus l''éclat est vif (diamant : 2,42 ; quartz : 1,54).',array['Éclat adamantin','Dispersion','Biréfringence']::text[],array['Diamant','Quartz']::text[]),
('Diffraction des rayons X','diffraction-des-rayons-x','cristallographie','Méthode d''analyse qui révèle la structure atomique d''un cristal ; c''est le moyen de référence pour identifier une espèce minérale.',array['Réseau cristallin']::text[],'{}'::text[]),
('Plan de séparation','plan-de-separation','cristallographie','Plan de rupture facile qui, contrairement au clivage, n''est pas lié à la structure mais à des macles ou à des inclusions (corindon, magnétite).',array['Clivage']::text[],array['Corindon','Magnétite']::text[]),
('Roche','roche','geologie','Assemblage naturel d''un ou plusieurs minéraux (parfois de verre ou de matière organique). On distingue les roches magmatiques, sédimentaires et métamorphiques.',array['Roche magmatique','Roche sédimentaire','Roche métamorphique']::text[],'{}'::text[]),
('Roche magmatique','roche-magmatique','geologie','Roche issue du refroidissement d''un magma : plutonique si elle cristallise lentement en profondeur (granite), volcanique si elle refroidit vite en surface (basalte).',array['Magma','Roche plutonique','Roche volcanique']::text[],'{}'::text[]),
('Roche plutonique','roche-plutonique','geologie','Roche magmatique refroidie lentement en profondeur, à cristaux visibles à l''œil nu : granite, diorite, gabbro, syénite.',array['Roche magmatique','Granite','Gabbro']::text[],array['Orthose','Quartz','Biotite']::text[]),
('Roche volcanique','roche-volcanique','geologie','Roche magmatique refroidie rapidement en surface, à grain fin ou vitreux : basalte, andésite, trachyte, rhyolite.',array['Roche magmatique','Basalte','Lave']::text[],array['Sanidine','Augite','Olivine']::text[]),
('Roche sédimentaire','roche-sedimentaire','geologie','Roche formée à la surface de la Terre par accumulation de débris, de restes d''êtres vivants ou par précipitation chimique : calcaire, grès, argile, évaporites.',array['Calcaire','Argile','Évaporite','Diagenèse']::text[],array['Calcite','Gypse','Halite']::text[]),
('Roche métamorphique','roche-metamorphique','geologie','Roche transformée à l''état solide par une augmentation de température et de pression : schiste, micaschiste, gneiss, marbre, quartzite.',array['Métamorphisme','Micaschiste','Gneiss','Marbre']::text[],array['Almandin','Disthène','Staurotide']::text[]),
('Magma','magma','geologie','Roche fondue, mêlée de cristaux et de gaz, formée en profondeur ; en refroidissant, il donne les roches magmatiques.',array['Lave','Roche magmatique']::text[],'{}'::text[]),
('Lave','lave','geologie','Magma émis en surface par un volcan, qui se solidifie en roche volcanique.',array['Magma','Roche volcanique','Basalte']::text[],'{}'::text[]),
('Granite','granite','geologie','Roche plutonique claire et grenue, formée essentiellement de quartz, de feldspaths et de micas ; elle constitue une grande partie du Massif central, de la Bretagne et des Vosges.',array['Roche plutonique','Pegmatite','Greisen']::text[],array['Quartz','Orthose','Microcline','Muscovite','Biotite']::text[]),
('Pegmatite','pegmatite','geologie','Roche magmatique à très gros cristaux, formée à partir des derniers liquides riches en eau et en éléments rares d''un granite ; source de béryl, tourmaline, topaze, lépidolite.',array['Granite','Roche plutonique']::text[],array['Béryl','Elbaïte','Schorl','Topaze','Lépidolite','Spodumène','Microcline']::text[]),
('Basalte','basalte','geologie','Roche volcanique sombre et fine, la plus répandue à la surface du globe ; ses cavités abritent souvent zéolites, calcédoine et améthyste.',array['Roche volcanique','Zéolite','Géode']::text[],array['Augite','Olivine','Stilbite','Améthyste','Calcédoine']::text[]),
('Gabbro','gabbro','geologie','Roche plutonique sombre de même composition que le basalte, riche en plagioclase et en pyroxène.',array['Basalte','Roche plutonique']::text[],array['Labradorite','Augite','Ilménite']::text[]),
('Péridotite','peridotite','geologie','Roche verte très riche en olivine, qui constitue le manteau supérieur ; on en trouve en nodules dans certains basaltes.',array['Manteau','Serpentinite']::text[],array['Olivine','Chromite','Pyrope']::text[]),
('Kimberlite','kimberlite','geologie','Roche volcanique venue de très grande profondeur, en cheminées étroites, qui remonte parfois le diamant du manteau.',array['Manteau']::text[],array['Diamant','Pyrope']::text[]),
('Syénite','syenite','geologie','Roche plutonique proche du granite mais pauvre ou dépourvue de quartz, riche en feldspaths ; les syénites néphéliniques contiennent des feldspathoïdes.',array['Granite']::text[],array['Néphéline','Sodalite','Aegyrine','Titanite']::text[]),
('Calcaire','calcaire','geologie','Roche sédimentaire composée surtout de calcite, souvent formée de coquilles et de débris d''organismes marins ; elle fait effervescence à l''acide.',array['Roche sédimentaire','Karst','Marbre']::text[],array['Calcite']::text[]),
('Argile','argile','geologie','Roche sédimentaire tendre formée de minéraux en feuillets microscopiques (kaolinite, illite…), plastique quand elle est humide.',array['Roche sédimentaire']::text[],array['Kaolinite']::text[]),
('Grès','gres','geologie','Roche sédimentaire formée de grains de sable (surtout de quartz) cimentés entre eux.',array['Roche sédimentaire']::text[],array['Quartz']::text[]),
('Silex','silex','geologie','Roche siliceuse très dure, faite de calcédoine et de quartz microcristallin, en rognons dans la craie ; taillé par les hommes préhistoriques.',array['Nodule']::text[],array['Calcédoine']::text[]),
('Évaporite','evaporite','geologie','Roche sédimentaire formée par évaporation d''eaux salées (lagunes, lacs) : gypse, anhydrite, halite, sylvite.',array['Roche sédimentaire','Rose des sables']::text[],array['Gypse','Anhydrite','Halite','Sylvite','Célestine']::text[]),
('Bauxite','bauxite','geologie','Roche résiduelle riche en hydroxydes d''aluminium, formée par altération sous climat chaud et humide ; principal minerai d''aluminium, nommé d''après Les Baux-de-Provence.',array['Latérite','Altération']::text[],array['Gibbsite','Goethite']::text[]),
('Latérite','laterite','geologie','Sol rouge des régions tropicales, enrichi en oxydes de fer et d''aluminium par le lessivage intense des roches.',array['Bauxite','Altération']::text[],array['Goethite','Hématite']::text[]),
('Schiste','schiste','geologie','Roche qui se débite en feuillets ; au sens strict, roche métamorphique faiblement transformée issue d''argiles.',array['Micaschiste','Schiste bleu']::text[],array['Muscovite','Clinochlore']::text[]),
('Micaschiste','micaschiste','geologie','Roche métamorphique feuilletée riche en micas et en quartz, contenant souvent grenat, staurotide ou disthène.',array['Schiste','Gneiss']::text[],array['Muscovite','Biotite','Almandin','Staurotide','Disthène']::text[]),
('Gneiss','gneiss','geologie','Roche métamorphique de haut degré, à bandes claires (quartz, feldspaths) et sombres (micas, amphiboles) alternées.',array['Micaschiste','Métamorphisme régional']::text[],array['Orthose','Biotite','Sillimanite','Almandin']::text[]),
('Marbre','marbre','geologie','Roche métamorphique issue d''un calcaire ou d''une dolomie recristallisés ; les marbres impurs livrent spinelle, corindon, phlogopite ou grenats.',array['Calcaire','Skarn']::text[],array['Calcite','Dolomite','Spinelle','Phlogopite','Corindon']::text[]),
('Quartzite','quartzite','geologie','Roche métamorphique très dure issue d''un grès, dont les grains de quartz se sont soudés.',array['Grès']::text[],array['Quartz']::text[]),
('Serpentinite','serpentinite','geologie','Roche verte au toucher gras issue de l''hydratation d''une péridotite, composée surtout de minéraux du groupe de la serpentine.',array['Péridotite','Ophiolite']::text[],array['Serpentine','Chromite','Magnésite','Brucite','Uvarovite']::text[]),
('Éclogite','eclogite','geologie','Roche métamorphique de très haute pression, formée de grenat rouge et de pyroxène vert (omphacite), témoin d''un enfouissement profond.',array['Métamorphisme','Schiste bleu']::text[],array['Pyrope','Almandin','Disthène']::text[]),
('Schiste bleu','schiste-bleu','geologie','Roche métamorphique de haute pression et basse température, colorée par le glaucophane, typique des anciennes zones de subduction (île de Groix, Alpes).',array['Éclogite','Subduction']::text[],array['Glaucophane','Épidote','Jadéite']::text[]),
('Skarn','skarn','geologie','Roche formée au contact entre un magma et un calcaire, par échanges chimiques ; riche en grenats, pyroxènes, vésuvianite, et souvent minéralisée (tungstène, cuivre, fer).',array['Métamorphisme de contact','Marbre']::text[],array['Grossulaire','Andradite','Vésuvianite','Diopside','Scheelite','Wollastonite']::text[]),
('Greisen','greisen','geologie','Roche claire à quartz et micas issue de l''altération d''un granite par des fluides chauds ; souvent riche en cassitérite, wolframite et topaze.',array['Granite','Hydrothermalisme']::text[],array['Cassitérite','Wolframite','Topaze','Muscovite']::text[]),
('Ophiolite','ophiolite','geologie','Fragment d''ancienne croûte océanique et de manteau charrié sur un continent (péridotites, serpentinites, gabbros, basaltes en coussins).',array['Serpentinite','Tectonique des plaques']::text[],array['Serpentine','Chromite']::text[]),
('Métamorphisme','metamorphisme','geologie','Transformation d''une roche à l''état solide sous l''effet de la température, de la pression et des fluides ; de nouveaux minéraux y apparaissent.',array['Métamorphisme de contact','Métamorphisme régional','Roche métamorphique']::text[],'{}'::text[]),
('Métamorphisme de contact','metamorphisme-de-contact','geologie','Métamorphisme provoqué par la chaleur d''un magma sur les roches qui l''entourent, dans une auréole de quelques centaines de mètres à quelques kilomètres.',array['Métamorphisme','Skarn']::text[],array['Andalousite','Wollastonite','Grossulaire','Cordiérite']::text[]),
('Métamorphisme régional','metamorphisme-regional','geologie','Métamorphisme à grande échelle lié à la formation des chaînes de montagnes, où les roches sont enfouies et chauffées.',array['Métamorphisme','Orogenèse']::text[],array['Almandin','Staurotide','Disthène','Sillimanite']::text[]),
('Hydrothermalisme','hydrothermalisme','geologie','Circulation d''eaux chaudes chargées d''éléments dissous dans les fissures des roches ; en refroidissant, elles déposent des minéraux qui forment les filons.',array['Filon','Fluide','Minéralisation']::text[],array['Quartz','Fluorite','Baryte','Galène','Sphalérite']::text[]),
('Fluide','fluide','geologie','Eau, gaz ou saumure circulant dans les roches, capable de dissoudre, transporter et redéposer des éléments ; moteur de la plupart des minéralisations.',array['Hydrothermalisme','Inclusion fluide']::text[],'{}'::text[]),
('Inclusion fluide','inclusion-fluide','geologie','Minuscule goutte de liquide, parfois avec une bulle de gaz, piégée dans un cristal ; elle renseigne sur la température et la composition du fluide d''origine.',array['Inclusion','Fluide']::text[],array['Quartz','Fluorite','Halite']::text[]),
('Filon','filon','geologie','Fracture de la roche remplie de minéraux déposés par des fluides ; les filons sont la source classique des beaux spécimens (quartz, fluorite, baryte, sulfures).',array['Hydrothermalisme','Gangue','Géode']::text[],array['Quartz','Fluorite','Baryte','Galène']::text[]),
('Fente alpine','fente-alpine','geologie','Fissure ouverte dans les roches métamorphiques des Alpes, tapissée de cristaux déposés par des fluides : quartz, adulaire, anatase, hématite, épidote, axinite.',array['Filon','Cristallier']::text[],array['Quartz','Anatase','Hématite','Épidote','Axinite','Titanite']::text[]),
('Cristallier','cristallier','geologie','Chercheur de cristaux en montagne, qui prospecte les fentes alpines ; métier et tradition anciens, notamment dans les Alpes françaises et suisses.',array['Fente alpine']::text[],array['Quartz']::text[]),
('Gisement','gisement','geologie','Lieu où un ou plusieurs minéraux sont concentrés naturellement ; en minéralogie, désigne aussi un site de récolte précis (mine, carrière, affleurement).',array['Gîte','Minéralisation','Localité type']::text[],'{}'::text[]),
('Gîte','gite','geologie','Concentration naturelle de minéraux, qu''elle soit exploitable ou non ; le terme est proche de gisement.',array['Gisement']::text[],'{}'::text[]),
('Minéralisation','mineralisation','geologie','Concentration de minéraux utiles dans une roche, ou ensemble des processus qui la produisent.',array['Gisement','Minerai','Hydrothermalisme']::text[],'{}'::text[]),
('Placer','placer','geologie','Gisement alluvial où des minéraux lourds et résistants (or, cassitérite, grenat, zircon, diamant) se sont concentrés dans les sables et graviers d''une rivière ou d''une plage.',array['Alluvion','Batée']::text[],array['Or','Cassitérite','Zircon','Diamant','Magnétite']::text[]),
('Alluvion','alluvion','geologie','Dépôt de sable, de graviers et de galets laissé par un cours d''eau.',array['Placer']::text[],array['Or','Quartz']::text[]),
('Batée','batee','geologie','Récipient évasé utilisé pour laver les alluvions en séparant, par des mouvements circulaires, les minéraux lourds (or, grenat, magnétite) des plus légers.',array['Placer']::text[],array['Or','Magnétite']::text[]),
('Zone d''oxydation','zone-d-oxydation','geologie','Partie supérieure d''un gisement, au-dessus de la nappe d''eau, où les sulfures primaires s''altèrent au contact de l''air et de l''eau en minéraux secondaires colorés (malachite, azurite, pyromorphite, cérusite…).',array['Minéral secondaire','Chapeau de fer','Zone de cémentation']::text[],array['Malachite','Azurite','Pyromorphite','Cérusite','Smithsonite','Wulfénite']::text[]),
('Zone de cémentation','zone-de-cementation','geologie','Niveau situé sous la zone d''oxydation, où les métaux dissous se redéposent en sulfures secondaires riches (chalcocite, covellite) : on parle d''enrichissement supergène.',array['Zone d''oxydation']::text[],array['Chalcocite','Covellite','Cuivre']::text[]),
('Chapeau de fer','chapeau-de-fer','geologie','Masse rouille d''hydroxydes de fer qui coiffe un gisement sulfuré altéré à l''affleurement (en anglais gossan) ; un indice classique pour les prospecteurs.',array['Zone d''oxydation']::text[],array['Goethite','Hématite','Jarosite']::text[]),
('Affleurement','affleurement','geologie','Endroit où la roche apparaît à la surface du sol, sans couverture de terre ou de végétation.',array['Gisement']::text[],'{}'::text[]),
('Mine','mine','geologie','Ensemble de travaux, souterrains ou à ciel ouvert, destinés à extraire un minerai ou une substance utile.',array['Galerie','Puits','Halde','Carrière']::text[],'{}'::text[]),
('Carrière','carriere','geologie','Exploitation, le plus souvent à ciel ouvert, de roches ou de matériaux (pierre, granulats, argile, talc…).',array['Mine']::text[],array['Talc','Calcite']::text[]),
('Galerie','galerie','geologie','Couloir souterrain horizontal ou peu incliné creusé dans une mine pour atteindre ou exploiter un filon.',array['Mine','Puits']::text[],'{}'::text[]),
('Puits','puits','geologie','Excavation verticale qui donne accès aux travaux souterrains d''une mine.',array['Mine','Galerie']::text[],'{}'::text[]),
('Halde','halde','geologie','Tas de déblais et de minerai pauvre rejetés près d''une mine ; ancien terrain de recherche des collectionneurs. Accès souvent réglementé, parfois pollué (métaux lourds, arsenic).',array['Mine','Terril']::text[],'{}'::text[]),
('Terril','terril','geologie','Colline artificielle formée des stériles des mines de charbon, typique du Nord et de la Lorraine.',array['Halde']::text[],'{}'::text[]),
('Karst','karst','geologie','Paysage façonné par la dissolution des calcaires : grottes, gouffres, dolines, rivières souterraines ; siège des stalactites et des stalagmites.',array['Calcaire','Stalactite']::text[],array['Calcite','Aragonite']::text[]),
('Diagenèse','diagenese','geologie','Ensemble des transformations qui changent un sédiment meuble en roche dure (tassement, cimentation), à basse température.',array['Roche sédimentaire']::text[],array['Calcite','Pyrite']::text[]),
('Altération','alteration','geologie','Transformation des roches et des minéraux à la surface par l''eau, l''air et le climat ; elle donne les sols, les argiles et les minéraux secondaires.',array['Érosion','Zone d''oxydation']::text[],array['Kaolinite','Goethite']::text[]),
('Érosion','erosion','geologie','Usure et transport des roches par l''eau, le vent, la glace ou la gravité.',array['Altération','Alluvion']::text[],'{}'::text[]),
('Fumerolle','fumerolle','geologie','Émission de gaz volcaniques chauds par une fissure du sol, qui dépose parfois soufre, hématite ou sels.',array['Roche volcanique']::text[],array['Soufre','Hématite']::text[]),
('Faille','faille','geologie','Cassure de l''écorce terrestre le long de laquelle les deux blocs ont glissé l''un par rapport à l''autre ; les fluides y circulent et y déposent souvent des filons.',array['Filon','Diaclase']::text[],'{}'::text[]),
('Diaclase','diaclase','geologie','Fissure d''une roche sans déplacement des deux côtés.',array['Faille']::text[],'{}'::text[]),
('Pli','pli','geologie','Déformation courbe de couches rocheuses sous l''effet de compressions.',array['Orogenèse']::text[],'{}'::text[]),
('Orogenèse','orogenese','geologie','Formation d''une chaîne de montagnes par collision de plaques, accompagnée de plis, de failles, de métamorphisme et de magmatisme (orogenèse hercynienne, alpine).',array['Tectonique des plaques','Métamorphisme régional']::text[],'{}'::text[]),
('Tectonique des plaques','tectonique-des-plaques','geologie','Théorie selon laquelle la surface de la Terre est découpée en plaques rigides qui se déplacent, s''écartent, coulissent ou plongent les unes sous les autres.',array['Subduction','Orogenèse']::text[],'{}'::text[]),
('Subduction','subduction','geologie','Plongée d''une plaque océanique sous une autre plaque ; elle produit volcanisme, séismes et roches de haute pression (schistes bleus, éclogites).',array['Tectonique des plaques','Schiste bleu']::text[],array['Glaucophane','Jadéite']::text[]),
('Manteau','manteau','geologie','Enveloppe de la Terre située entre la croûte et le noyau, épaisse de près de 2 900 km, formée surtout de péridotites solides.',array['Croûte','Péridotite']::text[],array['Olivine','Pyrope','Diamant']::text[]),
('Croûte','croute','geologie','Enveloppe superficielle et rigide de la Terre : croûte continentale (granitique, épaisse de 30 à 70 km) et croûte océanique (basaltique, environ 7 km).',array['Manteau']::text[],'{}'::text[]),
('Massif central','massif-central','geologie','Vieux massif français issu de la chaîne hercynienne (granites, gneiss, micaschistes), rajeuni par un volcanisme récent ; riche en filons de fluorite, baryte, quartz et sulfures.',array['Orogenèse hercynienne','Granite','Filon']::text[],array['Fluorite','Baryte','Stibine','Galène']::text[]),
('Orogenèse hercynienne','orogenese-hercynienne','geologie','Formation d''une grande chaîne de montagnes à la fin de l''ère primaire (il y a environ 380 à 290 millions d''années), dont les restes forment le Massif central, le Massif armoricain, les Vosges et les Ardennes. On dit aussi varisque.',array['Orogenèse','Massif central']::text[],'{}'::text[]),
('Échelle des temps géologiques','echelle-des-temps-geologiques','geologie','Découpage de l''histoire de la Terre (4,56 milliards d''années) en éons, ères, périodes et étages, établi grâce aux fossiles et aux datations radiométriques.',array['Datation']::text[],'{}'::text[]),
('Datation','datation','geologie','Détermination de l''âge d''une roche ou d''un minéral, notamment par la désintégration d''éléments radioactifs (uranium–plomb dans le zircon, par exemple).',array['Échelle des temps géologiques']::text[],array['Zircon','Monazite']::text[]),
('Fossile','fossile','geologie','Reste ou trace d''un être vivant conservé dans une roche ; il peut être remplacé par un minéral (pyrite, calcédoine, opale) en gardant sa forme.',array['Pseudomorphose','Roche sédimentaire']::text[],array['Pyrite','Calcédoine','Vivianite']::text[])
